window.TEXTOS_SEED["2cronicas"][1] = [
{s:"Salomão pede a sabedoria"},
{v:1,t:"Salomão, filho de Davi, firmou-se no seu reino; o Senhor seu Deus estava com ele e o engrandeceu sobremaneira.",n:"Os dois livros das Crônicas formavam na origem uma só obra. O segundo começa com o reinado de Salomão, o construtor do templo (capítulos 1 a 9), e depois acompanha só os reis de Judá, da divisão do reino até o exílio e o edito de Ciro."},
{v:2,t:"Salomão falou a todo o Israel, aos chefes de mil e de cem, aos juízes e a todos os príncipes de todo o Israel, chefes das famílias;"},
{v:3,t:"e foi, com toda a assembleia, ao lugar alto de Gabaon, porque ali estava a tenda da reunião de Deus, que Moisés, servo do Senhor, tinha feito no deserto.",n:"Para o cronista, o culto de Salomão em Gabaon é legítimo, porque ali estavam a tenda de Moisés e o altar dos holocaustos (1 Crônicas 16,39; 21,29)."},
{v:4,t:"A arca de Deus, porém, Davi a tinha trazido de Cariat-Iarim para o lugar que lhe tinha preparado, porque lhe tinha armado uma tenda em Jerusalém."},
{v:5,t:"E o altar de bronze feito por Beseleel, filho de Uri, filho de Hur, estava ali, diante da morada do Senhor; e ali Salomão e a assembleia buscaram o Senhor."},
{v:6,t:"Salomão subiu ali ao altar de bronze, diante do Senhor, junto à tenda da reunião, e ofereceu sobre ele mil holocaustos."},
{v:7,t:"Naquela noite, Deus apareceu a Salomão e lhe disse: Pede o que queres que eu te dê.",np:1},
{v:8,t:"Salomão respondeu a Deus: Tu usaste de grande bondade com Davi, meu pai, e me fizeste reinar em seu lugar."},
{v:9,t:"Agora, Senhor Deus, que se cumpra a palavra que deste a Davi, meu pai; porque tu me fizeste reinar sobre um povo numeroso como o pó da terra."},
{v:10,t:"Dá-me, pois, sabedoria e conhecimento, para que eu saiba sair e entrar à frente deste povo; pois quem poderia julgar este teu povo tão grande?"},
{v:11,t:"Deus respondeu a Salomão: Porque foi isto que desejaste no teu coração, e não pediste riquezas, nem bens, nem glória, nem a vida dos teus inimigos, nem mesmo vida longa, mas pediste para ti sabedoria e conhecimento para julgar o meu povo, sobre o qual te fiz reinar,"},
{v:12,t:"a sabedoria e o conhecimento te são dados; e te darei também riquezas, bens e glória, como não tiveram os reis que houve antes de ti, nem terão os que virão depois de ti."},
{v:13,t:"Salomão voltou do lugar alto de Gabaon, de diante da tenda da reunião, para Jerusalém, e reinou sobre Israel."},
{s:"A riqueza de Salomão"},
{v:14,t:"Salomão reuniu carros e cavaleiros: tinha mil e quatrocentos carros e doze mil cavaleiros, que distribuiu pelas cidades dos carros e junto do rei, em Jerusalém.",np:1,n:"Ver 1 Reis 10,26-29. O cronista põe aqui, logo depois do sonho de Gabaon, o cumprimento da promessa de riquezas."},
{v:15,t:"O rei fez que em Jerusalém a prata e o ouro fossem tão comuns como as pedras, e os cedros tão numerosos como os sicômoros que crescem na Sefelá."},
{v:16,t:"Os cavalos de Salomão vinham do Egito e de Cua; os mercadores do rei os compravam em Cua por um preço fixo."},
{v:17,t:"Um carro trazido do Egito custava seiscentos siclos de prata, e um cavalo, cento e cinquenta; e da mesma forma, por meio deles, eram exportados para todos os reis dos heteus e da Síria."},
{v:18,t:"Salomão decidiu construir uma casa ao nome do Senhor e um palácio real para si.",np:1}
];

window.TEXTOS_SEED["2cronicas"][2] = [
{s:"Salomão e Hiram, rei de Tiro"},
{v:1,t:"Salomão recrutou setenta mil carregadores e oitenta mil cortadores de pedra na montanha, e três mil e seiscentos capatazes para dirigi-los."},
{v:2,t:"E Salomão mandou dizer a Hiram, rei de Tiro: Como fizeste com Davi, meu pai, a quem enviaste madeira de cedro para construir uma casa onde habitasse,",np:1},
{v:3,t:"faze também comigo, pois vou construir uma casa ao nome do Senhor meu Deus, para consagrá-la a ele, para queimar diante dele incenso aromático, para a apresentação contínua dos pães e para os holocaustos da manhã e da tarde, dos sábados, das luas novas e das festas do Senhor nosso Deus, como é prescrito para sempre a Israel."},
{v:4,t:"A casa que vou construir será grande, porque o nosso Deus é maior que todos os deuses."},
{v:5,t:"Mas quem será capaz de lhe construir uma casa digna dele, se os céus, e os céus dos céus, não o podem conter? E quem sou eu para lhe construir uma casa, a não ser para queimar incenso diante dele?",n:"A mesma consciência aparece na oração da dedicação (6,18): Deus não cabe num templo; o templo é o lugar onde o povo o encontra e lhe presta culto."},
{v:6,t:"Envia-me, pois, um homem hábil em trabalhar o ouro, a prata, o bronze e o ferro, a púrpura, o carmesim e a púrpura violeta, e que saiba fazer esculturas, para trabalhar com os artesãos que tenho comigo em Judá e em Jerusalém, e que Davi, meu pai, preparou."},
{v:7,t:"Envia-me também do Líbano madeira de cedro, de cipreste e de sândalo, porque sei que os teus servos sabem cortar as árvores do Líbano; e os meus servos estarão com os teus servos,"},
{v:8,t:"para me prepararem madeira em grande quantidade, porque a casa que vou construir será grande e maravilhosa."},
{v:9,t:"Aos teus servos, os lenhadores que cortarem as árvores, darei vinte mil coros de trigo, vinte mil coros de cevada, vinte mil batos de vinho e vinte mil batos de azeite.",n:"Em 1 Reis 5,25, as provisões são para a casa de Hiram; aqui, para os operários."},
{v:10,t:"Hiram, rei de Tiro, respondeu numa carta que enviou a Salomão: Porque o Senhor ama o seu povo, ele te fez rei sobre ele.",np:1},
{v:11,t:"E acrescentou: Bendito seja o Senhor, Deus de Israel, que fez o céu e a terra, porque deu ao rei Davi um filho sábio, dotado de prudência e de inteligência, que vai construir uma casa ao Senhor e um palácio real para si!"},
{v:12,t:"Envio-te, pois, um homem hábil e muito entendido, o mestre Hiram,",n:"À letra, Hiram, meu pai: título de honra de um mestre artesão. Não é o rei, mas o artífice de 1 Reis 7,13-14."},
{v:13,t:"filho de uma mulher das filhas de Dã e de pai tírio. Sabe trabalhar o ouro, a prata, o bronze, o ferro, a pedra e a madeira, a púrpura, a púrpura violeta, o linho fino e o carmesim; sabe fazer toda espécie de esculturas e executar qualquer projeto que se lhe confie, com os teus artesãos e com os artesãos do meu senhor Davi, teu pai.",n:"Em 1 Reis 7,14, a mãe é da tribo de Neftali. Como Ooliab, companheiro de Beseleel no deserto, que também era da tribo de Dã (Êxodo 31,6)."},
{v:14,t:"Agora, pois, o trigo, a cevada, o azeite e o vinho de que falou o meu senhor, que ele os mande aos seus servos."},
{v:15,t:"Nós cortaremos no Líbano toda a madeira de que precisares e a levaremos em jangadas, por mar, até Jope; e tu a farás subir a Jerusalém."},
{v:16,t:"Salomão fez o recenseamento de todos os estrangeiros que viviam na terra de Israel, depois do recenseamento que Davi, seu pai, tinha feito; e encontraram-se cento e cinquenta e três mil e seiscentos.",np:1,n:"O cronista atribui o trabalho forçado aos estrangeiros, e não aos israelitas, como em 1 Reis 5,27; ver também 8,9."},
{v:17,t:"Deles, fez setenta mil carregadores, oitenta mil cortadores de pedra na montanha e três mil e seiscentos capatazes, para fazer trabalhar o povo."}
];

window.TEXTOS_SEED["2cronicas"][3] = [
{s:"A construção do templo"},
{v:1,t:"Salomão começou a construir a casa do Senhor em Jerusalém, no monte Moriá, onde o Senhor tinha aparecido a Davi, seu pai, no lugar que Davi tinha preparado, na eira de Ornã, o jebuseu.",n:"Moriá: o monte onde Abraão ia sacrificar Isaac (Gênesis 22,2). Só aqui a Bíblia identifica o monte do templo com o lugar do sacrifício de Abraão: onde Deus proveu o cordeiro, Israel oferecerá os seus sacrifícios."},
{v:2,t:"Começou a construção no segundo mês do quarto ano do seu reinado."},
{v:3,t:"Estas são as medidas que Salomão estabeleceu para a construção da casa de Deus: sessenta côvados de comprimento, segundo a medida antiga, e vinte côvados de largura.",np:1,n:"A medida antiga: o côvado de antes do exílio, um pouco maior que o côvado comum (Ezequiel 40,5)."},
{v:4,t:"O vestíbulo, na frente, tinha vinte côvados de comprimento, igual à largura da casa, e cento e vinte de altura; e ele o revestiu por dentro de ouro puro.",n:"Cento e vinte côvados, uns sessenta metros: uma torre desproporcionada ao edifício. Talvez se deva ler vinte, como em algumas versões antigas."},
{v:5,t:"Revestiu a sala maior de madeira de cipreste, que cobriu de ouro fino, e fez esculpir nela palmeiras e correntes."},
{v:6,t:"Adornou a casa com pedras preciosas, para lhe dar beleza."},
{v:7,t:"O ouro era ouro de Parvaim; com ele revestiu a casa, as vigas, os umbrais, as paredes e as portas; e esculpiu querubins nas paredes.",n:"Parvaim: região de localização desconhecida, famosa pelo seu ouro."},
{v:8,t:"Fez também a sala do Santo dos Santos: tinha vinte côvados de comprimento, igual à largura da casa, e vinte côvados de largura; e revestiu-a de ouro fino, no valor de seiscentos talentos.",np:1},
{v:9,t:"O peso dos pregos era de cinquenta siclos de ouro. Revestiu também de ouro as salas superiores."},
{v:10,t:"Na sala do Santo dos Santos fez dois querubins, obra de escultura, e revestiu-os de ouro."},
{v:11,t:"As asas dos querubins tinham vinte côvados de comprimento: uma asa do primeiro, de cinco côvados, tocava a parede da casa; e a outra asa, de cinco côvados, tocava a asa do outro querubim."},
{v:12,t:"Do mesmo modo, uma asa do segundo querubim, de cinco côvados, tocava a parede da casa; e a outra asa, de cinco côvados, tocava a asa do primeiro querubim."},
{v:13,t:"As asas destes querubins estendiam-se por vinte côvados. Eles estavam de pé, com o rosto voltado para a sala."},
{v:14,t:"Fez também o véu de púrpura violeta, de púrpura, de carmesim e de linho fino, e bordou nele querubins.",n:"O véu que fechava o Santo dos Santos; 1 Reis fala de portas. No templo reconstruído, será o véu que se rasgará na morte de Jesus (Marcos 15,38)."},
{v:15,t:"Diante da casa fez duas colunas de trinta e cinco côvados de altura, e o capitel que estava no alto de cada uma tinha cinco côvados.",np:1,n:"Em 1 Reis 7,15, dezoito côvados cada uma: talvez aqui se some a altura das duas."},
{v:16,t:"Fez também correntes em forma de colar e pô-las no alto das colunas; e fez cem romãs, que pôs nas correntes."},
{v:17,t:"Ergueu as colunas diante do templo, uma à direita e outra à esquerda; à da direita deu o nome de Jaquin, e à da esquerda, o de Booz."}
];

window.TEXTOS_SEED["2cronicas"][4] = [
{s:"Os objetos do templo"},
{v:1,t:"Fez também um altar de bronze de vinte côvados de comprimento, vinte côvados de largura e dez côvados de altura.",n:"O altar dos holocaustos, no átrio: 1 Reis não o descreve."},
{v:2,t:"Fez também o mar de metal fundido: tinha dez côvados de uma borda à outra, e era redondo; tinha cinco côvados de altura, e um cordão de trinta côvados media a sua circunferência.",np:1},
{v:3,t:"Por baixo dele, ao redor, havia figuras de bois, dez por côvado, que o cercavam em toda a volta; os bois estavam em duas fileiras, fundidos numa só peça com o mar.",n:"Em 1 Reis 7,24, coloquíntidas; as duas palavras hebraicas se parecem."},
{v:4,t:"Assentava sobre doze bois: três voltados para o norte, três para o oeste, três para o sul e três para o leste; o mar estava por cima deles, e as suas ancas ficavam todas para dentro."},
{v:5,t:"A sua espessura era de um palmo, e a borda era como a borda de um cálice, como a flor do lírio aberta. Levava três mil batos.",n:"Em 1 Reis 7,26: dois mil batos."},
{v:6,t:"Fez também dez bacias e pôs cinco à direita e cinco à esquerda, para nelas se lavar o que se oferecia em holocausto; o mar, porém, servia para as abluções dos sacerdotes."},
{v:7,t:"Fez os dez candelabros de ouro, segundo o modelo prescrito, e colocou-os no templo, cinco à direita e cinco à esquerda.",np:1},
{v:8,t:"Fez também dez mesas e colocou-as no templo, cinco à direita e cinco à esquerda; e fez cem bacias de aspersão de ouro."},
{v:9,t:"Fez o átrio dos sacerdotes e o grande átrio, com as suas portas, que revestiu de bronze."},
{v:10,t:"Colocou o mar do lado direito, a sudeste."},
{v:11,t:"Hiram fez também as panelas, as pás e as bacias de aspersão. Assim Hiram terminou a obra que fazia para o rei Salomão na casa de Deus:",np:1},
{v:12,t:"as duas colunas, os dois capitéis arredondados no alto das colunas, as duas redes para cobrir os dois capitéis arredondados no alto das colunas;"},
{v:13,t:"as quatrocentas romãs para as duas redes, duas fileiras de romãs em cada rede, para cobrir os dois capitéis arredondados no alto das colunas;"},
{v:14,t:"fez também as bases, e as bacias sobre as bases;"},
{v:15,t:"o mar, único, e os doze bois debaixo dele;"},
{v:16,t:"as panelas, as pás e os garfos. Todos esses objetos, o mestre Hiram os fez de bronze polido para o rei Salomão, para a casa do Senhor."},
{v:17,t:"O rei os fundiu na planície do Jordão, em moldes de argila, entre Sucot e Sareda."},
{v:18,t:"Salomão fez todos esses objetos em tão grande quantidade que não se pôde calcular o peso do bronze."},
{v:19,t:"Salomão fez também todos os objetos da casa de Deus: o altar de ouro e as mesas sobre as quais se colocavam os pães da proposição;",np:1},
{v:20,t:"os candelabros e as suas lâmpadas de ouro puro, para arderem, segundo o rito, diante do Debir;"},
{v:21,t:"as flores, as lâmpadas e as tenazes de ouro, do ouro mais puro;"},
{v:22,t:"as facas, as bacias de aspersão, as colheres e os incensórios de ouro puro. E, na entrada da casa, as portas interiores do Santo dos Santos e as portas da sala do templo eram de ouro."}
];

window.TEXTOS_SEED["2cronicas"][5] = [
{s:"A arca é levada para o templo"},
{v:1,t:"Assim ficou terminada toda a obra que Salomão fez para a casa do Senhor. E Salomão trouxe as coisas que Davi, seu pai, tinha consagrado: a prata, o ouro e todos os objetos, e os depositou nos tesouros da casa de Deus."},
{v:2,t:"Então Salomão reuniu em Jerusalém os anciãos de Israel, todos os chefes das tribos e os chefes das famílias dos filhos de Israel, para trazer da Cidade de Davi, isto é, de Sião, a arca da aliança do Senhor.",np:1},
{v:3,t:"Todos os homens de Israel reuniram-se junto do rei na festa, que é no sétimo mês.",n:"A festa das Tendas, a grande festa da colheita, no outono."},
{v:4,t:"Vieram todos os anciãos de Israel, e os levitas levaram a arca.",n:"Em 1 Reis 8,3, os sacerdotes. O cronista, fiel à Lei (Deuteronômio 10,8; 1 Crônicas 15,2), atribui aos levitas o transporte da arca."},
{v:5,t:"Levaram a arca, a tenda da reunião e todos os objetos sagrados que havia na tenda: os sacerdotes levitas os levavam."},
{v:6,t:"O rei Salomão e toda a assembleia de Israel, reunida junto dele diante da arca, sacrificavam ovelhas e bois em quantidade tal que não se podia contar nem calcular."},
{v:7,t:"Os sacerdotes introduziram a arca da aliança do Senhor no seu lugar, no Debir do templo, no Santo dos Santos, debaixo das asas dos querubins.",np:1},
{v:8,t:"Os querubins estendiam as asas sobre o lugar da arca, e cobriam por cima a arca e os seus varais."},
{v:9,t:"Os varais eram tão compridos que as suas pontas se viam diante do Debir, mas não se viam de fora; e a arca está lá até o dia de hoje.",n:"Até o dia de hoje: o cronista copia a frase da sua fonte, escrita antes da destruição do templo."},
{v:10,t:"Na arca não havia outra coisa senão as duas tábuas que Moisés ali tinha posto no Horeb, quando o Senhor fez aliança com os filhos de Israel, ao saírem do Egito."},
{s:"A glória do Senhor enche o templo"},
{v:11,t:"Quando os sacerdotes saíram do santuário — pois todos os sacerdotes que ali se encontravam se tinham santificado, sem observar a ordem das classes;",np:1},
{v:12,t:"e os levitas cantores, todos, os de Asaf, de Hemã e de Iditun, com os seus filhos e os seus irmãos, vestidos de linho fino, estavam de pé a oriente do altar, com címbalos, harpas e cítaras, e com eles cento e vinte sacerdotes que tocavam as trombetas —"},
{v:13,t:"quando todos juntos, os que tocavam as trombetas e os cantores, fizeram ouvir em uníssono uma só voz para louvar e dar graças ao Senhor, e ergueram a voz com as trombetas, os címbalos e os outros instrumentos de música, louvando o Senhor: Porque ele é bom, porque é eterna a sua misericórdia, então a casa de Deus encheu-se de uma nuvem,",n:"O cronista acrescenta a 1 Reis 8 o louvor dos levitas: é quando o povo canta a misericórdia de Deus que a glória desce sobre o templo."},
{v:14,t:"e os sacerdotes não puderam ficar ali para fazer o seu serviço, por causa da nuvem, porque a glória do Senhor enchia a casa de Deus."}
];

window.TEXTOS_SEED["2cronicas"][6] = [
{s:"O discurso de Salomão ao povo"},
{v:1,t:"Então Salomão disse: O Senhor disse que habitaria na nuvem escura;",n:"Deus habita na obscuridade: está presente, mas não se deixa ver."},
{v:2,t:"e eu te construí uma casa para morada, um lugar onde habites para sempre."},
{v:3,t:"Depois o rei voltou-se e abençoou toda a assembleia de Israel, enquanto toda a assembleia de Israel estava de pé,",np:1},
{v:4,t:"e disse: Bendito seja o Senhor, Deus de Israel, que falou com a sua boca a Davi, meu pai, e com a sua mão cumpriu o que dissera:"},
{v:5,t:"Desde o dia em que tirei do Egito o meu povo, não escolhi cidade alguma, entre todas as tribos de Israel, para nela se construir uma casa onde estivesse o meu nome, nem escolhi homem algum para ser chefe do meu povo Israel;"},
{v:6,t:"mas escolhi Jerusalém, para que ali estivesse o meu nome, e escolhi Davi, para que estivesse à frente do meu povo Israel.",n:"O texto de 1 Reis 8,16 parece ter perdido uma parte na cópia; o cronista a conserva: a escolha de Jerusalém e a de Davi andam juntas."},
{v:7,t:"Davi, meu pai, desejou construir uma casa ao nome do Senhor, Deus de Israel;"},
{v:8,t:"mas o Senhor disse a Davi, meu pai: Pensaste no teu coração em construir uma casa ao meu nome, e fizeste bem em pensar nisso;"},
{v:9,t:"mas não serás tu que construirás a casa, e sim o teu filho, que sairá das tuas entranhas: ele construirá a casa ao meu nome."},
{v:10,t:"O Senhor cumpriu a palavra que tinha dito: eu sucedi a Davi, meu pai, e sentei-me no trono de Israel, como o Senhor tinha dito, e construí a casa ao nome do Senhor, Deus de Israel."},
{v:11,t:"E ali coloquei a arca, onde está a aliança que o Senhor fez com os filhos de Israel."},
{s:"A oração de Salomão"},
{v:12,t:"Salomão pôs-se diante do altar do Senhor, em presença de toda a assembleia de Israel, e estendeu as mãos.",np:1},
{v:13,t:"Pois Salomão tinha feito um estrado de bronze, de cinco côvados de comprimento, cinco côvados de largura e três côvados de altura, e o tinha colocado no meio do átrio; subiu nele, ajoelhou-se diante de toda a assembleia de Israel, estendeu as mãos para o céu",n:"O estrado de bronze é um pormenor próprio do cronista: o rei ora no átrio, diante do povo, e não no santuário, reservado aos sacerdotes."},
{v:14,t:"e disse: Senhor, Deus de Israel, não há Deus como tu, nem no céu nem na terra; tu guardas a aliança e a misericórdia para com os teus servos que andam diante de ti de todo o coração."},
{v:15,t:"Cumpriste para com o teu servo Davi, meu pai, o que lhe tinhas dito: o que prometeste com a tua boca, cumpriste com a tua mão, como hoje se vê."},
{v:16,t:"Agora, pois, Senhor, Deus de Israel, guarda para o teu servo Davi, meu pai, o que lhe prometeste, dizendo: Não te faltará diante de mim um descendente que se sente no trono de Israel, contanto que os teus filhos vigiem o seu caminho, andando na minha lei como tu andaste diante de mim.",n:"Andando na minha lei: em 1 Reis 8,25, andando diante de mim. Para o cronista, a fidelidade se mede pela Lei."},
{v:17,t:"Agora, pois, Senhor, Deus de Israel, cumpra-se a palavra que disseste ao teu servo Davi!"},
{v:18,t:"Mas será que Deus habitará verdadeiramente com os homens na terra? Se os céus e os céus dos céus não te podem conter, quanto menos esta casa que construí!",np:1},
{v:19,t:"Mas volta-te para a oração e para a súplica do teu servo, Senhor meu Deus; ouve o clamor e a oração que o teu servo te dirige,"},
{v:20,t:"para que os teus olhos estejam abertos dia e noite sobre esta casa, sobre o lugar onde prometeste pôr o teu nome; para que ouças a oração que o teu servo fizer neste lugar."},
{v:21,t:"Ouve as súplicas do teu servo e do teu povo Israel, quando orarem neste lugar; ouve do lugar da tua morada, do céu; ouve e perdoa."},
{v:22,t:"Se alguém pecar contra o seu próximo, e lhe for imposto um juramento que o obrigue, e ele vier jurar diante do teu altar, nesta casa,",np:1},
{v:23,t:"ouve do céu e age; julga os teus servos, retribuindo ao culpado, fazendo recair sobre a sua cabeça o seu procedimento, e justificando o inocente, dando-lhe segundo a sua justiça."},
{v:24,t:"Se o teu povo Israel for derrotado pelo inimigo, por ter pecado contra ti, e depois se converter, louvar o teu nome, orar e suplicar diante de ti nesta casa,",np:1},
{v:25,t:"ouve do céu, perdoa o pecado do teu povo Israel e faze-os voltar à terra que deste a eles e aos seus pais."},
{v:26,t:"Se o céu se fechar e não houver chuva, porque pecaram contra ti, e eles orarem neste lugar, louvarem o teu nome e se converterem do seu pecado, por causa da aflição que lhes enviaste,",np:1},
{v:27,t:"ouve do céu e perdoa o pecado dos teus servos e do teu povo Israel, ensinando-lhes o bom caminho por onde devem andar; e manda a chuva sobre a tua terra, que deste ao teu povo como herança."},
{v:28,t:"Se houver na terra fome ou peste, ferrugem ou mangra, gafanhotos ou larvas; se o inimigo o oprimir, sitiando as suas cidades; qualquer praga, qualquer doença,",np:1},
{v:29,t:"toda oração, toda súplica que fizer qualquer homem do teu povo Israel, reconhecendo cada um a sua chaga e a sua dor e estendendo as mãos para esta casa,"},
{v:30,t:"ouve do céu, do lugar da tua morada, perdoa e dá a cada um segundo todos os seus caminhos, tu que conheces o seu coração, porque só tu conheces o coração dos filhos dos homens,"},
{v:31,t:"para que te temam e andem nos teus caminhos todos os dias que viverem sobre a terra que deste aos nossos pais."},
{v:32,t:"Também o estrangeiro, que não é do teu povo Israel, quando vier de uma terra distante por causa do teu grande nome, da tua mão forte e do teu braço estendido, quando vier orar nesta casa,",np:1,n:"A oração abre-se aos estrangeiros: o templo de Israel será casa de oração para todos os povos (Isaías 56,7; Marcos 11,17)."},
{v:33,t:"ouve do céu, do lugar da tua morada, e faze tudo o que o estrangeiro te pedir, para que todos os povos da terra conheçam o teu nome e te temam, como o teu povo Israel, e saibam que o teu nome é invocado sobre esta casa que construí."},
{v:34,t:"Se o teu povo sair à guerra contra os seus inimigos, pelo caminho por onde os enviares, e orarem a ti voltados para esta cidade que escolheste e para a casa que construí ao teu nome,",np:1},
{v:35,t:"ouve do céu a sua oração e a sua súplica e faze-lhes justiça."},
{v:36,t:"Se pecarem contra ti — pois não há homem que não peque — e tu, irritado, os entregares aos seus inimigos, e estes os levarem cativos para uma terra distante ou próxima;",np:1},
{v:37,t:"se, na terra para onde foram levados cativos, eles caírem em si e se converterem, e te suplicarem na terra do seu cativeiro, dizendo: Pecamos, agimos mal, fomos ímpios;"},
{v:38,t:"se voltarem a ti de todo o coração e de toda a alma, na terra do cativeiro para onde os levaram, e orarem voltados para a terra que deste aos seus pais, para a cidade que escolheste e para a casa que construí ao teu nome,"},
{v:39,t:"ouve do céu, do lugar da tua morada, a sua oração e as suas súplicas, faze-lhes justiça e perdoa ao teu povo, que pecou contra ti."},
{v:40,t:"Agora, meu Deus, que os teus olhos estejam abertos e os teus ouvidos atentos à oração feita neste lugar.",np:1},
{v:41,t:"Agora, pois, levanta-te, Senhor Deus, e vem para o teu repouso, tu e a arca do teu poder. Que os teus sacerdotes, Senhor Deus, se vistam de salvação, e os teus fiéis se alegrem no bem.",n:"Os dois últimos versículos citam o Salmo 132,8-10, em lugar do final de 1 Reis 8,50-53: o cronista termina a oração com a arca e com Davi."},
{v:42,t:"Senhor Deus, não rejeites a face do teu ungido; lembra-te dos favores prometidos a Davi, teu servo.",n:"Os favores prometidos a Davi: a aliança eterna de Isaías 55,3. A oração do templo termina pedindo o cumprimento da promessa messiânica."}
];

window.TEXTOS_SEED["2cronicas"][7] = [
{s:"A dedicação do templo"},
{v:1,t:"Quando Salomão acabou de orar, desceu fogo do céu e consumiu o holocausto e os sacrifícios, e a glória do Senhor encheu a casa.",n:"O fogo do céu, como na inauguração do altar do deserto (Levítico 9,24) e no altar de Davi (1 Crônicas 21,26): Deus aceita o templo."},
{v:2,t:"Os sacerdotes não podiam entrar na casa do Senhor, porque a glória do Senhor enchia a casa do Senhor."},
{v:3,t:"Todos os filhos de Israel, vendo descer o fogo e a glória do Senhor sobre a casa, prostraram-se com o rosto em terra, sobre o pavimento, adoraram e louvaram o Senhor: Porque ele é bom, porque é eterna a sua misericórdia."},
{v:4,t:"O rei e todo o povo ofereceram sacrifícios diante do Senhor.",np:1},
{v:5,t:"O rei Salomão ofereceu em sacrifício vinte e dois mil bois e cento e vinte mil ovelhas. Assim o rei e todo o povo dedicaram a casa de Deus."},
{v:6,t:"Os sacerdotes estavam nos seus postos, e os levitas com os instrumentos de música do Senhor, que o rei Davi tinha feito para louvar o Senhor, cantando os hinos de Davi: Porque é eterna a sua misericórdia. Os sacerdotes tocavam as trombetas diante deles, e todo o Israel estava de pé."},
{v:7,t:"Salomão consagrou o meio do átrio que ficava diante da casa do Senhor; porque ali ofereceu os holocaustos e a gordura dos sacrifícios de comunhão, uma vez que o altar de bronze que Salomão tinha feito não podia conter os holocaustos, as oblações e a gordura."},
{v:8,t:"Naquele tempo Salomão celebrou a festa durante sete dias, e com ele todo o Israel, uma assembleia muito grande, vinda desde a entrada de Emat até a torrente do Egito.",np:1},
{v:9,t:"No oitavo dia fizeram uma assembleia solene, porque tinham celebrado a dedicação do altar durante sete dias, e a festa durante sete dias.",n:"Sete dias de dedicação, seguidos dos sete dias da festa das Tendas, que terminava com uma assembleia solene no oitavo dia (Levítico 23,36)."},
{v:10,t:"No vigésimo terceiro dia do sétimo mês, despediu o povo para as suas tendas, alegre e de coração contente pelo bem que o Senhor tinha feito a Davi, a Salomão e a Israel, seu povo."},
{s:"O Senhor aparece de novo a Salomão"},
{v:11,t:"Salomão terminou a casa do Senhor e o palácio real, e realizou com êxito tudo o que tinha no coração fazer na casa do Senhor e no seu palácio.",np:1},
{v:12,t:"O Senhor apareceu a Salomão de noite e lhe disse: Ouvi a tua oração e escolhi para mim este lugar como casa de sacrifício."},
{v:13,t:"Se eu fechar o céu e não houver chuva, se eu ordenar aos gafanhotos que devorem a terra, se eu mandar a peste contra o meu povo,"},
{v:14,t:"e o meu povo, sobre o qual é invocado o meu nome, se humilhar, orar, buscar a minha face e se converter dos seus maus caminhos, eu o ouvirei do céu, perdoarei o seu pecado e curarei a sua terra.",n:"Resposta à oração de Salomão, própria do cronista: humilhar-se, orar, buscar a face de Deus e converter-se são o caminho da cura. É o critério com que ele julgará os reis de Judá."},
{v:15,t:"Agora os meus olhos estarão abertos e os meus ouvidos atentos à oração feita neste lugar;"},
{v:16,t:"porque agora escolhi e consagrei esta casa, para que o meu nome esteja nela para sempre; e os meus olhos e o meu coração estarão ali todos os dias."},
{v:17,t:"Quanto a ti, se andares diante de mim como andou Davi, teu pai, fazendo tudo o que te ordenei e guardando os meus estatutos e as minhas normas,",np:1},
{v:18,t:"firmarei o trono do teu reino, como prometi a Davi, teu pai, dizendo: Não te faltará um homem que governe Israel.",n:"Que governe Israel: eco de Miqueias 5,1, a profecia do chefe que sairá de Belém."},
{v:19,t:"Mas, se vos afastardes e abandonardes os meus estatutos e os meus mandamentos que vos propus, e fordes servir a outros deuses e adorá-los,"},
{v:20,t:"eu vos arrancarei da minha terra que vos dei, rejeitarei de diante de mim esta casa que consagrei ao meu nome, e farei dela objeto de provérbio e de zombaria entre todos os povos."},
{v:21,t:"E esta casa, que era tão elevada, será motivo de espanto para todos os que passarem junto dela, e dirão: Por que fez o Senhor isto a esta terra e a esta casa?"},
{v:22,t:"E responderão: Porque abandonaram o Senhor, Deus de seus pais, que os tirou da terra do Egito, e se apegaram a outros deuses, os adoraram e os serviram; por isso ele fez vir sobre eles todo este mal."}
];

window.TEXTOS_SEED["2cronicas"][8] = [
{s:"As obras de Salomão"},
{v:1,t:"Ao fim de vinte anos, durante os quais Salomão construiu a casa do Senhor e o seu palácio,"},
{v:2,t:"Salomão reconstruiu as cidades que Hiram lhe tinha dado e estabeleceu nelas os filhos de Israel.",n:"Em 1 Reis 9,11-13, é Salomão quem dá cidades a Hiram. O cronista não conta que o rei de Israel tenha cedido território da terra santa."},
{v:3,t:"Salomão foi a Emat-Soba e apoderou-se dela.",n:"A única campanha militar atribuída a Salomão, no território do antigo reino de Soba, ao norte."},
{v:4,t:"Reconstruiu Tadmor, no deserto, e todas as cidades de armazéns que construíra em Emat.",n:"Tadmor, a futura Palmira, oásis no deserto da Síria. Em 1 Reis 9,18 se lê Tamar."},
{v:5,t:"Reconstruiu Bet-Horon de cima e Bet-Horon de baixo, cidades fortificadas, com muralhas, portas e ferrolhos;"},
{v:6,t:"e também Baalat, e todas as cidades de armazéns que pertenciam a Salomão, todas as cidades dos carros e as cidades dos cavalos, e tudo o que Salomão quis construir em Jerusalém, no Líbano e em todo o território do seu domínio."},
{v:7,t:"Todo o povo que restava dos heteus, dos amorreus, dos ferezeus, dos heveus e dos jebuseus, que não eram de Israel,",np:1},
{v:8,t:"os seus descendentes, que tinham ficado depois deles na terra, e que os filhos de Israel não tinham exterminado, Salomão sujeitou-os ao trabalho forçado, até hoje."},
{v:9,t:"Mas dos filhos de Israel Salomão não fez escravo nenhum para as suas obras: eram os seus guerreiros, os chefes dos seus oficiais e os comandantes dos seus carros e da sua cavalaria."},
{v:10,t:"Os chefes dos intendentes do rei Salomão eram duzentos e cinquenta; tinham autoridade sobre o povo.",n:"1 Reis 9,23 diz quinhentos e cinquenta."},
{v:11,t:"Salomão fez subir a filha do faraó da Cidade de Davi para a casa que lhe tinha construído, porque dizia: A minha mulher não deve habitar na casa de Davi, rei de Israel, porque são santos os lugares onde entrou a arca do Senhor.",np:1,n:"Explicação própria do cronista: uma estrangeira não devia morar junto dos lugares santificados pela arca."},
{v:12,t:"Então Salomão ofereceu holocaustos ao Senhor sobre o altar do Senhor que tinha construído diante do vestíbulo,",np:1},
{v:13,t:"segundo o que era prescrito para cada dia, conforme o mandamento de Moisés: nos sábados, nas luas novas e nas festas, três vezes por ano: na festa dos Pães sem Fermento, na festa das Semanas e na festa das Tendas."},
{v:14,t:"Segundo as disposições de Davi, seu pai, estabeleceu as classes dos sacerdotes no seu serviço, e os levitas nos seus ofícios, para louvar e servir diante dos sacerdotes, segundo o que era prescrito para cada dia, e os porteiros, segundo as suas classes, em cada porta; porque assim o tinha ordenado Davi, homem de Deus."},
{v:15,t:"Não se afastaram em nada das ordens do rei a respeito dos sacerdotes e dos levitas, nem a respeito dos tesouros."},
{v:16,t:"Assim foi executada toda a obra de Salomão, desde o dia em que foram lançados os alicerces da casa do Senhor até o dia em que foi terminada. A casa do Senhor ficou concluída."},
{v:17,t:"Então Salomão foi a Asion-Gaber e a Elat, na costa do mar Vermelho, na terra de Edom.",np:1},
{v:18,t:"Hiram mandou-lhe, por meio dos seus servos, navios e marinheiros que conheciam o mar; e eles foram com os servos de Salomão a Ofir, tomaram de lá quatrocentos e cinquenta talentos de ouro e os trouxeram ao rei Salomão.",n:"1 Reis 9,28 diz quatrocentos e vinte."}
];

window.TEXTOS_SEED["2cronicas"][9] = [
{s:"A visita da rainha de Sabá"},
{v:1,t:"A rainha de Sabá ouviu falar da fama de Salomão e veio a Jerusalém pô-lo à prova com enigmas, com um séquito muito numeroso, com camelos carregados de perfumes, de ouro em grande quantidade e de pedras preciosas. Foi ter com Salomão e falou-lhe de tudo o que tinha no coração.",n:"Sabá ficava no sul da Arábia. Jesus lembrará a rainha do Sul, que veio dos confins da terra para ouvir a sabedoria de Salomão (Mateus 12,42)."},
{v:2,t:"Salomão respondeu a todas as suas perguntas: não houve nada tão oculto que Salomão não lhe explicasse."},
{v:3,t:"Quando a rainha de Sabá viu a sabedoria de Salomão, o palácio que ele tinha construído,"},
{v:4,t:"as iguarias da sua mesa, os aposentos dos seus oficiais, o serviço dos seus criados e as suas librés, os seus copeiros e as librés deles, e os holocaustos que ele oferecia na casa do Senhor, ficou sem fôlego,"},
{v:5,t:"e disse ao rei: Era verdade o que ouvi na minha terra acerca de ti e da tua sabedoria!"},
{v:6,t:"Eu não acreditava no que me contavam, até que vim e vi com os meus próprios olhos: e não me tinham contado nem a metade da grandeza da tua sabedoria! Superas a fama que ouvi."},
{v:7,t:"Felizes os teus homens, felizes estes teus servos, que estão sempre diante de ti e ouvem a tua sabedoria!"},
{v:8,t:"Bendito seja o Senhor teu Deus, que se agradou de ti e te pôs no seu trono, como rei para o Senhor teu Deus! Porque o teu Deus ama Israel e quer mantê-lo para sempre, constituiu-te rei sobre ele, para praticares o direito e a justiça.",n:"No seu trono: em 1 Reis 10,9, no trono de Israel. Para o cronista, o trono de Israel é o trono de Deus (1 Crônicas 28,5; 29,23)."},
{v:9,t:"Ela deu ao rei cento e vinte talentos de ouro, grande quantidade de perfumes e pedras preciosas. Nunca houve perfumes como os que a rainha de Sabá deu ao rei Salomão."},
{v:10,t:"Também os servos de Hiram e os servos de Salomão, que traziam ouro de Ofir, trouxeram madeira de sândalo e pedras preciosas.",np:1},
{v:11,t:"Com a madeira de sândalo o rei fez escadas para a casa do Senhor e para o palácio real, e cítaras e harpas para os cantores. Nunca se tinha visto coisa igual na terra de Judá."},
{v:12,t:"O rei Salomão deu à rainha de Sabá tudo o que ela desejou e pediu, mais do que ela tinha trazido ao rei. Depois ela voltou para a sua terra com os seus servos."},
{s:"A riqueza e a sabedoria de Salomão"},
{v:13,t:"O peso do ouro que chegava a Salomão cada ano era de seiscentos e sessenta e seis talentos de ouro,",np:1},
{v:14,t:"sem contar o que traziam os mercadores e os negociantes; e todos os reis da Arábia e os governadores do país traziam ouro e prata a Salomão."},
{v:15,t:"O rei Salomão fez duzentos escudos grandes de ouro batido, empregando seiscentos siclos de ouro batido em cada escudo;"},
{v:16,t:"e trezentos escudos pequenos de ouro batido, empregando trezentos siclos de ouro em cada escudo; e o rei os pôs na Casa da Floresta do Líbano."},
{v:17,t:"O rei fez também um grande trono de marfim e revestiu-o de ouro puro."},
{v:18,t:"O trono tinha seis degraus e um escabelo de ouro, presos ao trono; havia braços de um lado e de outro do assento, e dois leões de pé junto dos braços;"},
{v:19,t:"e doze leões estavam de pé sobre os seis degraus, de um lado e de outro. Nada de semelhante se fez em reino algum."},
{v:20,t:"Todas as taças em que o rei Salomão bebia eram de ouro, e todos os utensílios da Casa da Floresta do Líbano eram de ouro puro; a prata não tinha valor algum no tempo de Salomão."},
{v:21,t:"Porque os navios do rei iam a Társis com os servos de Hiram; e de três em três anos os navios de Társis voltavam trazendo ouro, prata, marfim, macacos e pavões.",n:"O cronista entende navios de Társis como navios que iam a Társis, no extremo ocidente; mas a frota partia do mar Vermelho (8,17-18). Em 1 Reis 10,22, a expressão designa navios de alto-mar."},
{v:22,t:"Assim o rei Salomão superou todos os reis da terra em riqueza e em sabedoria.",np:1},
{v:23,t:"Todos os reis da terra desejavam ver o rosto de Salomão, para ouvir a sabedoria que Deus lhe tinha posto no coração."},
{v:24,t:"E cada um lhe trazia o seu presente, todos os anos: objetos de prata e de ouro, vestes, armas, perfumes, cavalos e mulas."},
{v:25,t:"Salomão tinha quatro mil estrebarias para os cavalos e os carros, e doze mil cavaleiros, que distribuiu pelas cidades dos carros e junto do rei, em Jerusalém.",n:"1 Reis 5,6 diz quarenta mil estrebarias."},
{v:26,t:"Ele dominava sobre todos os reis, desde o rio Eufrates até a terra dos filisteus e até a fronteira do Egito.",n:"É a extensão da terra prometida a Abraão (Gênesis 15,18)."},
{v:27,t:"O rei fez que em Jerusalém a prata fosse tão comum como as pedras, e os cedros tão numerosos como os sicômoros que crescem na Sefelá."},
{v:28,t:"Traziam cavalos para Salomão do Egito e de todos os países."},
{s:"A morte de Salomão"},
{v:29,t:"O resto dos feitos de Salomão, os primeiros e os últimos, está escrito na história do profeta Natã, na profecia de Aías, de Silo, e nas visões do vidente Ado a respeito de Jeroboão, filho de Nabat.",np:1,n:"O cronista não fala das mulheres estrangeiras de Salomão nem da sua idolatria na velhice (1 Reis 11): o construtor do templo permanece, para ele, um rei ideal."},
{v:30,t:"Salomão reinou em Jerusalém sobre todo o Israel quarenta anos."},
{v:31,t:"Salomão adormeceu com seus pais e foi sepultado na Cidade de Davi, seu pai; e seu filho Roboão reinou em seu lugar."}
];

window.TEXTOS_SEED["2cronicas"][10] = [
{s:"A divisão do reino"},
{v:1,t:"Roboão foi a Siquém, porque todo o Israel se tinha reunido ali para o proclamar rei."},
{v:2,t:"Jeroboão, filho de Nabat, que estava no Egito, para onde tinha fugido do rei Salomão, soube disso e voltou do Egito.",n:"O cronista supõe conhecida a história de Jeroboão e da profecia de Aías (1 Reis 11,26-40)."},
{v:3,t:"Mandaram chamá-lo, e Jeroboão veio com todo o Israel; e disseram a Roboão:"},
{v:4,t:"Teu pai tornou pesado o nosso jugo; alivia agora a dura servidão de teu pai e o jugo pesado que ele pôs sobre nós, e nós te serviremos."},
{v:5,t:"Ele lhes respondeu: Voltai a mim daqui a três dias. E o povo se retirou."},
{v:6,t:"O rei Roboão consultou os anciãos que tinham estado a serviço de Salomão, seu pai, durante a vida dele, e perguntou-lhes: Que me aconselhais responder a este povo?",np:1},
{v:7,t:"Eles lhe disseram: Se fores bondoso para com este povo, se lhes agradares e lhes falares com boas palavras, eles serão teus servos para sempre.",n:"Em 1 Reis 12,7: se hoje te fizeres servo deste povo. O cronista suaviza a expressão."},
{v:8,t:"Mas ele rejeitou o conselho que os anciãos lhe tinham dado e consultou os jovens que tinham crescido com ele e que estavam a seu serviço,"},
{v:9,t:"e perguntou-lhes: Que me aconselhais responder a este povo, que me disse: Alivia o jugo que teu pai pôs sobre nós?"},
{v:10,t:"Os jovens que tinham crescido com ele responderam: Assim falarás a este povo, que te disse: Teu pai tornou pesado o nosso jugo, alivia-o tu; assim lhes dirás: O meu dedo mínimo é mais grosso que a cintura de meu pai."},
{v:11,t:"Meu pai vos impôs um jugo pesado, e eu o tornarei ainda mais pesado; meu pai vos castigou com açoites, e eu vos castigarei com escorpiões."},
{v:12,t:"Ao terceiro dia, Jeroboão e todo o povo vieram ter com Roboão, como o rei tinha dito: Voltai a mim daqui a três dias.",np:1},
{v:13,t:"O rei respondeu-lhes duramente; o rei Roboão rejeitou o conselho dos anciãos"},
{v:14,l:["e falou-lhes segundo o conselho dos jovens:","Meu pai tornou pesado o vosso jugo,","e eu o tornarei ainda mais pesado;","meu pai vos castigou com açoites,","e eu vos castigarei com escorpiões."]},
{v:15,t:"O rei não atendeu o povo, porque Deus tinha disposto assim, para cumprir a palavra que o Senhor tinha dito a Jeroboão, filho de Nabat, por meio de Aías, de Silo."},
{v:16,l:["Todo o Israel, vendo que o rei não os queria ouvir, respondeu ao rei:","Que parte temos nós com Davi?","Que herança com o filho de Jessé?","Às tuas tendas, Israel!","Agora, Davi, cuida da tua casa!","E todo o Israel foi para as suas tendas."]},
{v:17,t:"Quanto aos filhos de Israel que moravam nas cidades de Judá, Roboão reinou sobre eles.",np:1},
{v:18,t:"O rei Roboão enviou Adoram, encarregado dos trabalhos forçados, mas os filhos de Israel o apedrejaram, e ele morreu. Então o rei Roboão subiu depressa ao seu carro e fugiu para Jerusalém.",n:"Adoram é o Adoniram de 1 Reis 12,18."},
{v:19,t:"Assim Israel se separou da casa de Davi, até hoje.",n:"Para o cronista, o reino do Norte, separado da casa de Davi e do templo, afastou-se do caminho de Deus; só falará dele quando a sua história se cruzar com a de Judá."}
];

window.TEXTOS_SEED["2cronicas"][11] = [
{s:"Semeías impede a guerra"},
{v:1,t:"Roboão chegou a Jerusalém e reuniu a casa de Judá e de Benjamim, cento e oitenta mil guerreiros escolhidos, para combater contra Israel e devolver o reino a Roboão."},
{v:2,t:"Mas a palavra do Senhor foi dirigida a Semeías, homem de Deus, nestes termos:"},
{v:3,t:"Dize a Roboão, filho de Salomão, rei de Judá, e a todo o Israel que está em Judá e em Benjamim:",n:"Todo o Israel que está em Judá e em Benjamim: para o cronista, o verdadeiro Israel é o que permanece fiel à casa de Davi e ao templo."},
{v:4,t:"Assim diz o Senhor: Não subais a combater contra os vossos irmãos; volte cada um para sua casa, porque isto vem de mim. Eles ouviram as palavras do Senhor e desistiram de marchar contra Jeroboão."},
{s:"Roboão fortifica Judá"},
{v:5,t:"Roboão habitou em Jerusalém e construiu cidades fortificadas em Judá.",np:1},
{v:6,t:"Reconstruiu Belém, Etam, Técua,"},
{v:7,t:"Bet-Sur, Soco, Odolam,"},
{v:8,t:"Gat, Maresa, Zif,"},
{v:9,t:"Aduram, Laquis, Azeca,"},
{v:10,t:"Saraá, Aialon e Hebron, cidades fortificadas em Judá e em Benjamim.",n:"Uma linha de fortalezas ao sul e a oeste de Jerusalém, talvez construída depois da invasão de Sesac (12,2-4)."},
{v:11,t:"Reforçou as fortalezas e pôs nelas comandantes e depósitos de víveres, de azeite e de vinho."},
{v:12,t:"Em cada cidade pôs escudos e lanças, e as fortificou muito. Assim Judá e Benjamim ficaram com ele."},
{s:"Os sacerdotes e os levitas vêm para Judá"},
{v:13,t:"Os sacerdotes e os levitas que havia em todo o Israel vieram de todo o seu território para junto dele.",np:1},
{v:14,t:"Os levitas deixaram as suas pastagens e as suas propriedades e vieram para Judá e para Jerusalém, porque Jeroboão e os seus filhos os tinham excluído do sacerdócio do Senhor,"},
{v:15,t:"e ele tinha estabelecido sacerdotes para os lugares altos, para os demônios e para os bezerros que tinha feito.",n:"Os demônios: à letra, os bodes, divindades do deserto (Levítico 17,7). Os bezerros de ouro de Betel e de Dã (1 Reis 12,28-31)."},
{v:16,t:"Depois deles, de todas as tribos de Israel, os que tinham posto o coração em buscar o Senhor, Deus de Israel, vieram a Jerusalém para oferecer sacrifícios ao Senhor, Deus de seus pais.",n:"Também do Norte vinham os fiéis: o Israel das doze tribos se reúne em torno do templo."},
{v:17,t:"Assim fortaleceram o reino de Judá e sustentaram Roboão, filho de Salomão, durante três anos; porque durante três anos andaram no caminho de Davi e de Salomão."},
{s:"A família de Roboão"},
{v:18,t:"Roboão tomou por mulher Maalat, filha de Jerimot, filho de Davi, e de Abiail, filha de Eliab, filho de Jessé.",np:1},
{v:19,t:"Ela lhe deu os filhos Jeús, Samarias e Zoom."},
{v:20,t:"Depois dela, tomou Maaca, filha de Absalão, que lhe deu Abias, Etai, Ziza e Salomit."},
{v:21,t:"Roboão amou Maaca, filha de Absalão, mais do que todas as suas mulheres e concubinas; pois teve dezoito mulheres e sessenta concubinas, e gerou vinte e oito filhos e sessenta filhas."},
{v:22,t:"Roboão estabeleceu Abias, filho de Maaca, como chefe e príncipe entre os seus irmãos, porque pensava fazê-lo rei."},
{v:23,t:"Agiu com habilidade, distribuindo alguns dos seus filhos por todas as regiões de Judá e de Benjamim, por todas as cidades fortificadas; deu-lhes víveres em abundância e procurou para eles muitas mulheres."}
];

window.TEXTOS_SEED["2cronicas"][12] = [
{s:"A invasão de Sesac"},
{v:1,t:"Quando o reino de Roboão se consolidou e ele se tornou forte, abandonou a lei do Senhor, e todo o Israel com ele.",n:"O esquema do cronista aparece aqui com clareza: a infidelidade traz o castigo; a humildade, o perdão (7,14)."},
{v:2,t:"No quinto ano do reinado de Roboão, Sesac, rei do Egito, subiu contra Jerusalém — porque tinham sido infiéis ao Senhor —",n:"O faraó Sheshonq I, por volta de 925 antes de Cristo (1 Reis 14,25)."},
{v:3,t:"com mil e duzentos carros e sessenta mil cavaleiros; e era sem número a multidão que veio com ele do Egito: líbios, suquitas e etíopes."},
{v:4,t:"Tomou as cidades fortificadas de Judá e chegou até Jerusalém."},
{v:5,t:"Então o profeta Semeías foi ter com Roboão e com os chefes de Judá, que se tinham reunido em Jerusalém, fugindo de Sesac, e disse-lhes: Assim diz o Senhor: Vós me abandonastes; por isso também eu vos abandonei nas mãos de Sesac.",np:1},
{v:6,t:"Os chefes de Israel e o rei humilharam-se e disseram: O Senhor é justo!"},
{v:7,t:"Quando o Senhor viu que eles se tinham humilhado, a palavra do Senhor foi dirigida a Semeías nestes termos: Eles se humilharam; não os destruirei, mas em breve lhes darei a salvação, e a minha ira não se derramará sobre Jerusalém por meio de Sesac."},
{v:8,t:"Contudo, ficarão sujeitos a ele, para que conheçam a diferença entre servir a mim e servir aos reinos da terra.",n:"Servir a Deus é liberdade; servir aos poderes do mundo é escravidão."},
{v:9,t:"Sesac, rei do Egito, subiu contra Jerusalém e levou os tesouros da casa do Senhor e os tesouros do palácio real; levou tudo, e também os escudos de ouro que Salomão tinha feito.",np:1},
{v:10,t:"Em lugar deles, o rei Roboão fez escudos de bronze e confiou-os aos chefes da guarda que vigiavam a entrada do palácio real."},
{v:11,t:"Cada vez que o rei ia à casa do Senhor, os guardas vinham e os levavam, e depois os traziam de volta à sala da guarda."},
{v:12,t:"Porque se humilhou, a ira do Senhor afastou-se dele, e ele não foi destruído completamente; e em Judá ainda havia coisas boas."},
{v:13,t:"O rei Roboão consolidou-se em Jerusalém e reinou. Tinha quarenta e um anos quando começou a reinar, e reinou dezessete anos em Jerusalém, a cidade que o Senhor escolheu entre todas as tribos de Israel para nela pôr o seu nome. Sua mãe chamava-se Naama, a amonita.",np:1},
{v:14,t:"Ele fez o mal, porque não dispôs o seu coração para buscar o Senhor."},
{v:15,t:"Os feitos de Roboão, os primeiros e os últimos, estão escritos na história do profeta Semeías e do vidente Ado, com as genealogias. E houve guerra contínua entre Roboão e Jeroboão."},
{v:16,t:"Roboão adormeceu com seus pais e foi sepultado na Cidade de Davi; e seu filho Abias reinou em seu lugar.",n:"Abias é o Abiam de 1 Reis 15."}
];

window.TEXTOS_SEED["2cronicas"][13] = [
{s:"Abias, rei de Judá"},
{v:1,t:"No décimo oitavo ano do rei Jeroboão, Abias começou a reinar sobre Judá."},
{v:2,t:"Reinou três anos em Jerusalém. Sua mãe chamava-se Micaia, filha de Uriel, de Gabaá. Houve guerra entre Abias e Jeroboão.",n:"Micaia: em 11,20 e em 1 Reis 15,2, Maaca, filha de Absalão; talvez neta dele, por meio de uma filha casada com Uriel."},
{v:3,t:"Abias entrou em combate com um exército de valentes guerreiros, quatrocentos mil homens escolhidos; e Jeroboão dispôs-se em linha de batalha contra ele com oitocentos mil homens escolhidos, guerreiros valentes.",n:"Números enormes, à maneira do cronista: a vitória virá de Deus, e não do número."},
{s:"O discurso de Abias"},
{v:4,t:"Abias subiu ao monte Semaraim, que está na montanha de Efraim, e disse: Ouvi-me, Jeroboão e todo o Israel!",np:1,n:"O rei de Judá faz um verdadeiro sermão às tribos do Norte: é o cronista que fala por ele."},
{v:5,t:"Não sabeis que o Senhor, Deus de Israel, deu para sempre a Davi o reino sobre Israel, a ele e aos seus filhos, por uma aliança de sal?",n:"Aliança de sal: aliança inviolável. O sal, que conserva, era sinal de duração e acompanhava os sacrifícios (Levítico 2,13; Números 18,19)."},
{v:6,t:"Mas Jeroboão, filho de Nabat, servo de Salomão, filho de Davi, levantou-se e revoltou-se contra o seu senhor."},
{v:7,t:"Juntaram-se a ele homens sem valor, gente perversa, que se impuseram a Roboão, filho de Salomão, quando Roboão era jovem e de coração tímido, e não pôde resistir-lhes."},
{v:8,t:"E agora pensais poder resistir ao reino do Senhor, que está nas mãos dos filhos de Davi, porque sois uma grande multidão e tendes convosco os bezerros de ouro que Jeroboão vos fez como deuses.",n:"O reino do Senhor nas mãos dos filhos de Davi: é o centro da teologia do cronista."},
{v:9,t:"Não expulsastes os sacerdotes do Senhor, os filhos de Aarão, e os levitas, e não fizestes para vós sacerdotes como os povos das outras terras? Qualquer um que venha com um novilho e sete carneiros para ser consagrado torna-se sacerdote dos que não são deuses."},
{v:10,t:"Mas, quanto a nós, o Senhor é o nosso Deus, e não o abandonamos; os sacerdotes que servem ao Senhor são filhos de Aarão, e os levitas estão no seu serviço."},
{v:11,t:"Oferecem ao Senhor holocaustos todas as manhãs e todas as tardes, e o incenso aromático; põem os pães sobre a mesa pura e acendem todas as tardes o candelabro de ouro com as suas lâmpadas. Porque nós guardamos os mandamentos do Senhor nosso Deus, e vós o abandonastes."},
{v:12,t:"Vede: Deus está conosco, à nossa frente, e os seus sacerdotes com as trombetas de guerra, para tocarem o alarme contra vós. Filhos de Israel, não combatais contra o Senhor, Deus de vossos pais, porque não tereis êxito!"},
{s:"A vitória de Judá"},
{v:13,t:"Jeroboão, porém, tinha mandado uma emboscada dar a volta para atacá-los pela retaguarda; assim, eles estavam diante de Judá, e a emboscada por trás.",np:1},
{v:14,t:"Quando os de Judá se voltaram, viram que tinham de combater pela frente e pela retaguarda. Clamaram ao Senhor, e os sacerdotes tocaram as trombetas."},
{v:15,t:"Os homens de Judá deram o grito de guerra; e, quando os homens de Judá gritaram, Deus derrotou Jeroboão e todo o Israel diante de Abias e de Judá."},
{v:16,t:"Os filhos de Israel fugiram diante de Judá, e Deus os entregou nas suas mãos."},
{v:17,t:"Abias e o seu povo infligiram-lhes uma grande derrota: caíram mortos de Israel quinhentos mil homens escolhidos."},
{v:18,t:"Assim os filhos de Israel foram humilhados naquele tempo, e os filhos de Judá prevaleceram, porque se tinham apoiado no Senhor, Deus de seus pais."},
{v:19,t:"Abias perseguiu Jeroboão e tomou-lhe algumas cidades: Betel e as suas aldeias, Jesana e as suas aldeias, Efron e as suas aldeias."},
{v:20,t:"Jeroboão não recuperou mais as suas forças durante a vida de Abias; o Senhor o feriu, e ele morreu."},
{v:21,t:"Abias, porém, fortaleceu-se; tomou catorze mulheres e gerou vinte e dois filhos e dezesseis filhas.",np:1},
{v:22,t:"O resto dos feitos de Abias, o seu procedimento e as suas palavras estão escritos no comentário do profeta Ado.",n:"Comentário: em hebraico midrash, palavra que designará mais tarde a interpretação das Escrituras."},
{v:23,t:"Abias adormeceu com seus pais, e o sepultaram na Cidade de Davi; e seu filho Asa reinou em seu lugar. No seu tempo, a terra ficou em paz durante dez anos.",n:"Nas traduções que seguem a numeração grega, este versículo é 14,1, e os versículos do capítulo 14 são numerados de 2 a 15."}
];

window.TEXTOS_SEED["2cronicas"][14] = [
{s:"Asa, rei de Judá"},
{v:1,t:"Asa fez o que é bom e reto aos olhos do Senhor seu Deus. Suprimiu os altares estrangeiros e os lugares altos,"},
{v:2,t:"quebrou as estelas e cortou os postes sagrados;"},
{v:3,t:"e ordenou a Judá que buscasse o Senhor, Deus de seus pais, e praticasse a lei e os mandamentos."},
{v:4,t:"Suprimiu de todas as cidades de Judá os lugares altos e os altares de incenso; e o reino esteve em paz sob ele.",n:"Segundo 15,17 e 1 Reis 15,14, os lugares altos não foram suprimidos: talvez se trate aqui dos santuários pagãos."},
{v:5,t:"Construiu cidades fortificadas em Judá, porque a terra estava em paz e não houve guerra contra ele naqueles anos, pois o Senhor lhe deu descanso.",np:1},
{v:6,t:"Disse a Judá: Construamos estas cidades e cerquemo-las de muralhas, torres, portas e ferrolhos, enquanto a terra ainda está livre de guerras; porque buscamos o Senhor nosso Deus, e ele nos buscou e nos deu descanso de todos os lados. Construíram, pois, e prosperaram.",n:"E ele nos buscou: assim a Nova Vulgata, com a versão grega; o hebraico repete: nós o buscamos."},
{v:7,t:"Asa tinha um exército de trezentos mil homens de Judá, que traziam escudo grande e lança, e duzentos e oitenta mil de Benjamim, que traziam escudo pequeno e atiravam com o arco; todos eram guerreiros valentes."},
{s:"A vitória sobre Zara, o etíope"},
{v:8,t:"Zara, o etíope, saiu contra eles com um exército de um milhão de homens e trezentos carros, e chegou até Maresa.",np:1,n:"Zara, o etíope, ou cuchita: talvez um chefe das tribos do sul, a serviço do Egito."},
{v:9,t:"Asa saiu ao seu encontro, e dispuseram-se em linha de batalha no vale que fica ao norte de Maresa.",n:"Ao norte de Maresa: assim a Nova Vulgata, com a versão grega; o hebraico diz no vale de Sefata, junto de Maresa."},
{v:10,t:"Asa invocou o Senhor seu Deus e disse: Senhor, ninguém como tu socorre o fraco diante do forte. Ajuda-nos, Senhor nosso Deus, porque em ti nos apoiamos e em teu nome viemos contra esta multidão. Senhor, tu és o nosso Deus: que nenhum homem prevaleça contra ti!"},
{v:11,t:"O Senhor derrotou os etíopes diante de Asa e de Judá, e os etíopes fugiram."},
{v:12,t:"Asa e o povo que estava com ele os perseguiram até Gerara; e caíram tantos etíopes que não restou deles nenhum com vida, porque foram destroçados diante do Senhor e do seu exército. E levaram um despojo muito grande."},
{v:13,t:"Atacaram todas as cidades em volta de Gerara, porque o terror do Senhor tinha caído sobre elas; e saquearam todas as cidades, porque havia nelas muito despojo."},
{v:14,t:"Atacaram também os acampamentos dos pastores e levaram ovelhas e camelos em grande quantidade. Depois voltaram para Jerusalém."}
];

window.TEXTOS_SEED["2cronicas"][15] = [
{s:"A profecia de Azarias"},
{v:1,t:"O Espírito de Deus veio sobre Azarias, filho de Oded,"},
{v:2,t:"que saiu ao encontro de Asa e lhe disse: Ouvi-me, Asa e todo o Judá e Benjamim! O Senhor está convosco enquanto estais com ele. Se o buscardes, ele se deixará encontrar por vós; mas, se o abandonardes, ele vos abandonará.",n:"É o princípio que o cronista aplica a toda a história dos reis de Judá."},
{v:3,t:"Durante muito tempo, Israel esteve sem o Deus verdadeiro, sem sacerdote que o ensinasse e sem lei.",n:"Talvez uma alusão ao tempo dos juízes, ou ao reino do Norte; Oseias usará palavras semelhantes (Oseias 3,4)."},
{v:4,t:"Mas na sua angústia voltaram-se para o Senhor, Deus de Israel, buscaram-no, e ele se deixou encontrar por eles."},
{v:5,t:"Naqueles tempos, não havia paz para quem saía nem para quem entrava, mas grandes perturbações pesavam sobre todos os habitantes das terras."},
{v:6,t:"Uma nação era esmagada por outra, e uma cidade por outra, porque Deus os perturbava com toda espécie de angústias."},
{v:7,t:"Mas vós, sede fortes e não deixeis cair os braços, porque o vosso trabalho terá a sua recompensa."},
{s:"A reforma de Asa"},
{v:8,t:"Quando Asa ouviu estas palavras e esta profecia, cobrou ânimo e fez desaparecer os ídolos abomináveis de toda a terra de Judá e de Benjamim e das cidades que tinha tomado na montanha de Efraim; e restaurou o altar do Senhor que estava diante do vestíbulo do Senhor.",np:1},
{v:9,t:"Reuniu todo o Judá e Benjamim, e com eles os que tinham vindo de Efraim, de Manassés e de Simeão; porque muitos de Israel tinham passado para o seu lado, vendo que o Senhor seu Deus estava com ele."},
{v:10,t:"Reuniram-se em Jerusalém no terceiro mês do décimo quinto ano do reinado de Asa.",n:"O terceiro mês é o da festa das Semanas, que a tradição judaica ligou à aliança do Sinai: a renovação da aliança acontece nesse tempo."},
{v:11,t:"Naquele dia ofereceram ao Senhor, do despojo que tinham trazido, setecentos bois e sete mil ovelhas."},
{v:12,t:"E comprometeram-se, por uma aliança, a buscar o Senhor, Deus de seus pais, de todo o coração e de toda a alma;"},
{v:13,t:"e todo aquele que não buscasse o Senhor, Deus de Israel, seria morto, pequeno ou grande, homem ou mulher.",n:"A dureza da pena reflete a lei antiga contra a idolatria (Deuteronômio 13,7-10; 17,2-7)."},
{v:14,t:"Juraram ao Senhor em alta voz, com aclamações, ao som das trombetas e das cornetas."},
{v:15,t:"Todo o Judá alegrou-se com o juramento, porque tinham jurado de todo o coração e o tinham buscado com toda a vontade, e ele se deixou encontrar por eles. E o Senhor lhes deu descanso de todos os lados."},
{v:16,t:"O rei Asa chegou a destituir sua avó Maaca da dignidade de rainha-mãe, porque ela tinha feito um ídolo abominável para Aserá. Asa abateu o ídolo, despedaçou-o e o queimou na torrente do Cedron.",np:1,n:"À letra, sua mãe; ver 1 Reis 15,10 e a nota."},
{v:17,t:"Mas os lugares altos não foram suprimidos de Israel; contudo o coração de Asa foi íntegro durante toda a sua vida."},
{v:18,t:"Levou para a casa de Deus as coisas que seu pai tinha consagrado e as que ele mesmo tinha consagrado: prata, ouro e objetos."},
{v:19,t:"E não houve guerra até o trigésimo quinto ano do reinado de Asa."}
];

window.TEXTOS_SEED["2cronicas"][16] = [
{s:"A aliança de Asa com a Síria"},
{v:1,t:"No trigésimo sexto ano do reinado de Asa, Baasa, rei de Israel, subiu contra Judá e fortificou Ramá, para impedir a entrada e a saída das tropas de Asa, rei de Judá.",n:"Segundo 1 Reis 16,8, Baasa já tinha morrido no vigésimo sexto ano de Asa. A cronologia do cronista é difícil de harmonizar com a dos Reis."},
{v:2,t:"Então Asa tirou prata e ouro dos tesouros da casa do Senhor e do palácio real e os enviou a Ben-Adad, rei da Síria, que morava em Damasco, com esta mensagem:"},
{v:3,t:"Há uma aliança entre mim e ti, como houve entre meu pai e teu pai. Envio-te prata e ouro: rompe a tua aliança com Baasa, rei de Israel, para que ele se retire de mim."},
{v:4,t:"Ben-Adad atendeu o rei Asa e enviou os chefes do seu exército contra as cidades de Israel; e eles devastaram Aion, Dã, Abel-Maim e todas as cidades de armazéns de Neftali."},
{v:5,t:"Quando Baasa soube disso, deixou de fortificar Ramá e suspendeu a sua obra."},
{v:6,t:"Então o rei Asa reuniu todo o Judá, e levaram as pedras e a madeira com que Baasa fortificava Ramá; e com elas fortificou Gabaá e Masfa."},
{s:"O vidente Hanani"},
{v:7,t:"Naquele tempo, o vidente Hanani foi ter com Asa, rei de Judá, e lhe disse: Porque te apoiaste no rei da Síria e não te apoiaste no Senhor teu Deus, o exército do rei da Síria escapou das tuas mãos.",np:1},
{v:8,t:"Os etíopes e os líbios não formavam um exército enorme, com carros e cavaleiros em grande número? E, porque te apoiaste no Senhor, ele os entregou nas tuas mãos."},
{v:9,t:"Porque os olhos do Senhor percorrem toda a terra, para fortalecer aqueles cujo coração é íntegro para com ele. Nisto agiste como um insensato; por isso, daqui em diante, terás guerras.",n:"Os olhos do Senhor percorrem toda a terra: a mesma imagem em Zacarias 4,10."},
{v:10,t:"Asa irritou-se contra o vidente e mandou metê-lo no cepo, porque estava furioso contra ele por causa disso; e naquele tempo Asa oprimiu também alguns do povo.",n:"O primeiro profeta perseguido por um rei de Judá. Jeremias também será posto no cepo (Jeremias 20,2)."},
{s:"A morte de Asa"},
{v:11,t:"Os feitos de Asa, os primeiros e os últimos, estão escritos no livro dos Reis de Judá e de Israel.",np:1},
{v:12,t:"No trigésimo nono ano do seu reinado, Asa adoeceu dos pés, com uma doença muito grave; e nem na sua doença buscou o Senhor, mas confiou nos médicos.",n:"Não se condena a medicina, mas a confiança nos médicos em lugar de Deus. O Eclesiástico dirá: honra o médico, porque também ele foi criado pelo Senhor (Eclesiástico 38,1-15)."},
{v:13,t:"Asa adormeceu com seus pais e morreu no quadragésimo primeiro ano do seu reinado."},
{v:14,t:"Sepultaram-no no túmulo que tinha mandado cavar para si na Cidade de Davi. Puseram-no sobre um leito cheio de aromas e de perfumes de toda espécie, preparados segundo a arte dos perfumistas, e em sua honra acenderam um fogo enorme.",n:"Não era cremação: queimavam-se perfumes em honra do rei morto (Jeremias 34,5)."}
];

window.TEXTOS_SEED["2cronicas"][17] = [
{s:"Josafá, rei de Judá"},
{v:1,t:"Seu filho Josafá reinou em seu lugar e fortaleceu-se contra Israel."},
{v:2,t:"Pôs tropas em todas as cidades fortificadas de Judá e estabeleceu guarnições na terra de Judá e nas cidades de Efraim que Asa, seu pai, tinha tomado."},
{v:3,t:"O Senhor esteve com Josafá, porque ele andou nos primeiros caminhos de seu pai e não buscou os baals,"},
{v:4,t:"mas buscou o Deus de seu pai e andou nos seus mandamentos, e não fez como Israel."},
{v:5,t:"O Senhor consolidou o reino nas suas mãos, e todo o Judá trazia presentes a Josafá, que teve riquezas e glória em abundância."},
{v:6,t:"O seu coração tornou-se ousado nos caminhos do Senhor, e ele suprimiu ainda de Judá os lugares altos e os postes sagrados.",n:"Mas 20,33 dirá que os lugares altos não desapareceram."},
{s:"Os mestres da Lei"},
{v:7,t:"No terceiro ano do seu reinado, enviou os seus oficiais Ben-Hail, Abdias, Zacarias, Natanael e Miqueias para ensinar nas cidades de Judá;",np:1,n:"Primeira notícia de uma missão para ensinar a Lei ao povo: prefigura a obra de Esdras e dos levitas (Neemias 8,7-9)."},
{v:8,t:"e com eles os levitas Semeías, Natanias, Zabadias, Asael, Semiramot, Jônatas, Adonias e Tobias, e os sacerdotes Elisama e Jorão."},
{v:9,t:"Ensinavam em Judá, tendo consigo o livro da lei do Senhor; percorriam todas as cidades de Judá e instruíam o povo."},
{s:"O poder de Josafá"},
{v:10,t:"O terror do Senhor caiu sobre todos os reinos das terras em volta de Judá, e não ousaram fazer guerra contra Josafá.",np:1},
{v:11,t:"Também dos filisteus traziam presentes a Josafá e um tributo em prata; e os árabes lhe traziam rebanhos: sete mil e setecentos carneiros e sete mil e setecentos bodes."},
{v:12,t:"Josafá foi crescendo cada vez mais em poder; e construiu em Judá fortalezas e cidades de armazéns."},
{v:13,t:"Tinha muitos recursos nas cidades de Judá e, em Jerusalém, guerreiros valentes."},
{v:14,t:"Este é o seu recenseamento, segundo as suas famílias. De Judá, os chefes de mil: Ednas, o chefe, com trezentos mil guerreiros valentes;",np:1},
{v:15,t:"depois dele, o chefe Joanã, com duzentos e oitenta mil;"},
{v:16,t:"depois dele, Amasias, filho de Zecri, que se tinha oferecido ao Senhor, com duzentos mil guerreiros valentes.",n:"Que se tinha oferecido ao Senhor: talvez um voluntário para a guerra santa."},
{v:17,t:"De Benjamim: Eliada, guerreiro valente, com duzentos mil homens armados de arco e de escudo;"},
{v:18,t:"depois dele, Jozabad, com cento e oitenta mil homens armados para a guerra."},
{v:19,t:"Estes estavam a serviço do rei, sem contar os que o rei tinha posto nas cidades fortificadas de todo o Judá.",n:"Mais de um milhão de homens: números que exprimem a bênção de Deus sobre o rei fiel."}
];

window.TEXTOS_SEED["2cronicas"][18] = [
{s:"Josafá e Acab; o profeta Miqueias"},
{v:1,t:"Josafá teve riquezas e glória em abundância, e aparentou-se com Acab.",n:"Pelo casamento do seu filho Jorão com Atalia, filha de Acab (21,6; 2 Reis 8,18). O capítulo segue quase palavra por palavra 1 Reis 22."},
{v:2,t:"Alguns anos depois, desceu a Samaria, para visitar Acab. Acab matou para ele e para o povo que o acompanhava ovelhas e bois em grande quantidade, e convenceu-o a subir contra Ramot de Galaad."},
{v:3,t:"Acab, rei de Israel, disse a Josafá, rei de Judá: Queres vir comigo contra Ramot de Galaad? Josafá respondeu: Eu sou como tu, o meu povo como o teu povo; estaremos contigo na guerra."},
{v:4,t:"Mas Josafá disse ao rei de Israel: Consulta primeiro, por favor, a palavra do Senhor.",np:1},
{v:5,t:"O rei de Israel reuniu os profetas, quatrocentos homens, e perguntou-lhes: Devemos ir combater contra Ramot de Galaad, ou devo desistir? Eles responderam: Sobe, e Deus a entregará nas mãos do rei."},
{v:6,t:"Mas Josafá perguntou: Não há aqui mais algum profeta do Senhor, para o consultarmos?"},
{v:7,t:"O rei de Israel respondeu a Josafá: Ainda há um homem por meio do qual poderíamos consultar o Senhor; mas eu o detesto, porque nunca me profetiza o bem, sempre o mal: é Miqueias, filho de Jemla. Josafá disse: Não fale o rei desse modo!"},
{v:8,t:"Então o rei de Israel chamou um eunuco e disse: Depressa, traze Miqueias, filho de Jemla!"},
{v:9,t:"O rei de Israel e Josafá, rei de Judá, estavam sentados cada um no seu trono, com as vestes reais, na eira, à entrada da porta de Samaria; e todos os profetas profetizavam diante deles.",np:1},
{v:10,t:"Sedecias, filho de Canaana, tinha feito para si chifres de ferro e dizia: Assim diz o Senhor: Com estes chifrarás os arameus até exterminá-los."},
{v:11,t:"E todos os profetas profetizavam do mesmo modo, dizendo: Sobe a Ramot de Galaad e serás bem-sucedido; o Senhor a entregará nas mãos do rei."},
{v:12,t:"O mensageiro que tinha ido chamar Miqueias disse-lhe: Olha: os profetas, a uma só voz, anunciam o bem ao rei; que a tua palavra seja como a deles, e anuncia o bem.",np:1},
{v:13,t:"Miqueias respondeu: Pela vida do Senhor, direi o que o meu Deus me disser!"},
{v:14,t:"Quando chegou junto do rei, o rei lhe perguntou: Miqueias, devemos ir combater contra Ramot de Galaad, ou devo desistir? Ele respondeu: Subi e sereis bem-sucedidos; os inimigos serão entregues nas vossas mãos."},
{v:15,t:"O rei lhe disse: Quantas vezes terei de te fazer jurar que não me dirás senão a verdade em nome do Senhor?"},
{v:16,l:["Miqueias respondeu:","Vi todo o Israel","disperso pelos montes,","como ovelhas sem pastor;","e o Senhor disse: Estes não têm senhor; volte cada um em paz para a sua casa."],n:"Ovelhas sem pastor: o rei, pastor do povo, vai morrer. Jesus terá compaixão das multidões, que eram como ovelhas sem pastor (Marcos 6,34)."},
{v:17,t:"O rei de Israel disse a Josafá: Não te disse que ele não me profetiza o bem, mas só o mal?"},
{v:18,t:"Miqueias continuou: Ouvi, pois, a palavra do Senhor: Vi o Senhor sentado no seu trono, e todo o exército do céu de pé à sua direita e à sua esquerda.",np:1},
{v:19,t:"E o Senhor disse: Quem enganará Acab, rei de Israel, para que suba e caia em Ramot de Galaad? E um dizia uma coisa, e outro dizia outra."},
{v:20,t:"Então se adiantou um espírito, pôs-se diante do Senhor e disse: Eu o enganarei. O Senhor lhe perguntou: Como?"},
{v:21,t:"Ele respondeu: Irei e serei um espírito de mentira na boca de todos os seus profetas. O Senhor disse: Tu o enganarás, e serás bem-sucedido: vai e faze assim.",n:"A linguagem antiga atribui a Deus até o engano dos falsos profetas: o Senhor entrega Acab à mentira que ele mesmo preferiu à verdade."},
{v:22,t:"Eis, pois, que o Senhor pôs um espírito de mentira na boca destes teus profetas; e o Senhor pronunciou contra ti a desgraça."},
{v:23,t:"Então Sedecias, filho de Canaana, aproximou-se, deu uma bofetada em Miqueias e disse: Por que caminho o Espírito do Senhor passou de mim, para falar contigo?",np:1},
{v:24,t:"Miqueias respondeu: Tu o verás no dia em que entrares num quarto retirado para te esconder."},
{v:25,t:"O rei de Israel disse: Prendei Miqueias e levai-o a Amon, governador da cidade, e a Joás, filho do rei,"},
{v:26,t:"e dizei-lhes: Assim diz o rei: Ponde este homem na prisão e sustentai-o com um pouco de pão e um pouco de água, até que eu volte em paz."},
{v:27,t:"Miqueias disse: Se voltares em paz, o Senhor não falou por mim. E acrescentou: Ouvi, povos todos!"},
{s:"A morte de Acab"},
{v:28,t:"O rei de Israel e Josafá, rei de Judá, subiram contra Ramot de Galaad.",np:1},
{v:29,t:"O rei de Israel disse a Josafá: Vou disfarçar-me para entrar na batalha; tu, porém, veste as tuas roupas. O rei de Israel disfarçou-se, e entraram na batalha."},
{v:30,t:"O rei da Síria tinha dado esta ordem aos comandantes dos seus carros: Não ataqueis ninguém, pequeno ou grande, senão somente o rei de Israel."},
{v:31,t:"Quando os comandantes dos carros viram Josafá, disseram: É o rei de Israel! E cercaram-no para atacá-lo. Mas Josafá gritou, e o Senhor o socorreu, e Deus os afastou dele.",n:"O cronista acrescenta: o Senhor o socorreu. O grito de Josafá torna-se uma oração."},
{v:32,t:"Os comandantes dos carros perceberam que não era o rei de Israel, e deixaram de persegui-lo."},
{v:33,t:"Mas um homem retesou o arco ao acaso e atingiu o rei de Israel entre as juntas da couraça. O rei disse ao cocheiro: Volta o carro e tira-me do combate, porque estou ferido."},
{v:34,t:"Mas a batalha tornou-se violenta naquele dia; o rei de Israel manteve-se de pé no seu carro, diante dos arameus, até a tarde, e morreu ao pôr do sol."}
];

window.TEXTOS_SEED["2cronicas"][19] = [
{s:"O vidente Jeú repreende Josafá"},
{v:1,t:"Josafá, rei de Judá, voltou em paz para a sua casa, em Jerusalém."},
{v:2,t:"O vidente Jeú, filho de Hanani, saiu ao seu encontro e disse ao rei Josafá: Devias tu ajudar o ímpio e ser amigo dos que odeiam o Senhor? Por isso a ira do Senhor caiu sobre ti."},
{v:3,t:"Mas há em ti coisas boas, porque fizeste desaparecer da terra os postes sagrados e dispuseste o teu coração para buscar a Deus."},
{s:"A reforma da justiça"},
{v:4,t:"Josafá habitou em Jerusalém. Depois voltou a percorrer o povo, desde Bersabeia até a montanha de Efraim, e o reconduziu ao Senhor, Deus de seus pais.",np:1,n:"O nome de Josafá significa o Senhor julga: o cronista lhe atribui a organização da justiça."},
{v:5,t:"Estabeleceu juízes na terra, em todas as cidades fortificadas de Judá, cidade por cidade,"},
{v:6,t:"e disse aos juízes: Vede bem o que fazeis, porque não julgais em nome dos homens, mas em nome do Senhor, que está convosco quando pronunciais a sentença."},
{v:7,t:"Que o temor do Senhor esteja convosco; agi com cuidado, porque no Senhor nosso Deus não há injustiça, nem acepção de pessoas, nem aceitação de presentes.",n:"Ver Deuteronômio 1,17; 10,17; 16,19."},
{v:8,t:"Também em Jerusalém Josafá estabeleceu levitas, sacerdotes e chefes das famílias de Israel, para julgarem em nome do Senhor e para as causas dos habitantes de Jerusalém.",np:1,n:"Um tribunal central em Jerusalém, como prescreve Deuteronômio 17,8-13."},
{v:9,t:"E deu-lhes estas ordens: Assim agireis, no temor do Senhor, com fidelidade e com coração íntegro."},
{v:10,t:"Em toda causa que vos for apresentada pelos vossos irmãos que habitam nas suas cidades, seja questão de sangue, seja de lei, de mandamento, de estatutos ou de normas, adverti-os, para que não se tornem culpados diante do Senhor e a ira não caia sobre vós e sobre os vossos irmãos. Assim fareis, e não sereis culpados."},
{v:11,t:"O sumo sacerdote Amarias presidirá sobre vós em todos os assuntos do Senhor, e Zabadias, filho de Ismael, chefe da casa de Judá, em todos os assuntos do rei; e os levitas estarão à vossa disposição como oficiais. Sede fortes e agi, e o Senhor estará com o homem de bem.",n:"A distinção entre os assuntos de Deus e os assuntos do rei anuncia a organização da comunidade depois do exílio."}
];

window.TEXTOS_SEED["2cronicas"][20] = [
{s:"A invasão dos moabitas e dos amonitas"},
{v:1,t:"Depois disso, os moabitas e os amonitas, e com eles alguns meunitas, vieram atacar Josafá.",n:"Meunitas: assim a Nova Vulgata, com a versão grega; o hebraico repete amonitas. Eram talvez tribos de Maon, a sudeste do mar Morto (1 Crônicas 4,41)."},
{v:2,t:"Vieram avisar Josafá: Uma grande multidão vem contra ti do outro lado do mar, de Edom; e já estão em Asason-Tamar, que é Engadi.",n:"Do outro lado do mar Morto. Edom: assim a Nova Vulgata; o hebraico diz Aram, palavra quase igual na escrita. Engadi, oásis na margem ocidental do mar Morto."},
{v:3,t:"Josafá teve medo e resolveu buscar o Senhor; e proclamou um jejum para todo o Judá."},
{v:4,t:"Judá reuniu-se para implorar o socorro do Senhor; de todas as cidades de Judá vieram buscar o Senhor."},
{s:"A oração de Josafá"},
{v:5,t:"Josafá pôs-se de pé no meio da assembleia de Judá e de Jerusalém, na casa do Senhor, diante do átrio novo,",np:1},
{v:6,t:"e disse: Senhor, Deus de nossos pais, não és tu o Deus que está nos céus, e não dominas sobre todos os reinos das nações? Na tua mão estão a força e o poder, e ninguém te pode resistir."},
{v:7,t:"Não foste tu, nosso Deus, que expulsaste os habitantes desta terra diante do teu povo Israel, e a deste para sempre à descendência de Abraão, teu amigo?",n:"Abraão, amigo de Deus: o título aparece também em Isaías 41,8 e em Tiago 2,23."},
{v:8,t:"Eles habitaram nela e construíram nela um santuário ao teu nome, dizendo:"},
{v:9,t:"Se vier sobre nós a desgraça, a espada do castigo, a peste ou a fome, nós nos apresentaremos diante desta casa e diante de ti, porque o teu nome está nesta casa; clamaremos a ti na nossa angústia, e tu nos ouvirás e nos salvarás.",n:"Josafá lembra a oração de Salomão (6,28-30) e a resposta de Deus (7,13-14)."},
{v:10,t:"E agora, eis que os amonitas, os moabitas e os da montanha de Seir, cujo território não permitiste a Israel invadir quando saía do Egito, e que ele evitou sem destruí-los,",n:"Ver Deuteronômio 2,4-19."},
{v:11,t:"eis que nos pagam vindo expulsar-nos da tua propriedade, que nos deste em herança."},
{v:12,t:"Ó nosso Deus, não os julgarás? Porque não temos força diante desta grande multidão que vem contra nós, e não sabemos o que fazer; mas os nossos olhos estão voltados para ti.",n:"Não sabemos o que fazer, mas os nossos olhos estão voltados para ti: uma das orações mais simples e mais confiantes da Bíblia."},
{v:13,t:"Todo o Judá estava de pé diante do Senhor, com as suas crianças, as suas mulheres e os seus filhos."},
{s:"A profecia de Jaziel"},
{v:14,t:"Então o Espírito do Senhor veio, no meio da assembleia, sobre Jaziel, filho de Zacarias, filho de Banaías, filho de Jeiel, filho de Matanias, levita dos filhos de Asaf,",np:1,n:"Um levita cantor profetiza: para o cronista, os cantores do templo são também profetas (1 Crônicas 25,1)."},
{v:15,t:"e ele disse: Escutai, todo o Judá, habitantes de Jerusalém, e tu, rei Josafá! Assim vos diz o Senhor: Não temais nem vos assusteis diante desta grande multidão, porque a guerra não é vossa, mas de Deus.",n:"A guerra não é vossa, mas de Deus: palavra que lembra a de Davi diante de Golias (1 Samuel 17,47)."},
{v:16,t:"Amanhã descereis contra eles: eis que eles sobem pela subida de Sis, e os encontrareis no fim do vale, diante do deserto de Jeruel."},
{v:17,t:"Não sereis vós que combatereis; ficai apenas firmes, e vereis a salvação que o Senhor vos dará, Judá e Jerusalém. Não temais nem vos assusteis; amanhã saí ao encontro deles, e o Senhor estará convosco.",n:"Ficai firmes e vereis a salvação do Senhor: as palavras de Moisés junto ao mar Vermelho (Êxodo 14,13-14)."},
{v:18,t:"Josafá inclinou-se com o rosto em terra, e todo o Judá e os habitantes de Jerusalém prostraram-se diante do Senhor, para adorá-lo."},
{v:19,t:"E os levitas, dos filhos de Caat e dos filhos de Coré, levantaram-se para louvar o Senhor, Deus de Israel, em voz muito alta."},
{s:"A vitória pelo louvor"},
{v:20,t:"De manhã cedo levantaram-se e partiram para o deserto de Técua. Quando partiam, Josafá, de pé, disse: Ouvi-me, Judá e habitantes de Jerusalém! Crede no Senhor vosso Deus, e estareis seguros; crede nos seus profetas, e sereis bem-sucedidos.",np:1,n:"Eco de Isaías 7,9: se não crerdes, não permanecereis. Em hebraico, crer e estar seguro vêm da mesma raiz, a do Amém."},
{v:21,t:"E, depois de se aconselhar com o povo, pôs cantores diante do Senhor, para que, com vestes sagradas, marchassem à frente do exército e louvassem, dizendo: Dai graças ao Senhor, porque é eterna a sua misericórdia."},
{v:22,t:"No momento em que começaram os cânticos de louvor, o Senhor lançou emboscadas contra os amonitas, os moabitas e os da montanha de Seir, que tinham vindo contra Judá, e eles foram derrotados.",n:"O louvor precede a vitória e a produz: é Deus quem combate."},
{v:23,t:"Os amonitas e os moabitas levantaram-se contra os habitantes da montanha de Seir, para exterminá-los e destruí-los; e, quando acabaram com os habitantes de Seir, voltaram-se uns contra os outros e se destruíram mutuamente."},
{v:24,t:"Quando Judá chegou ao alto de onde se avista o deserto, olhou para a multidão, e só havia cadáveres estendidos por terra: ninguém tinha escapado."},
{v:25,t:"Josafá e o seu povo foram recolher os despojos e encontraram entre eles muitos animais, bens, vestes e objetos preciosos; tomaram tanto que não podiam levar tudo, e passaram três dias recolhendo o despojo, porque era muito grande."},
{v:26,t:"No quarto dia reuniram-se no vale de Beraca, onde bendisseram o Senhor; por isso deram àquele lugar o nome de vale de Beraca, isto é, da Bênção, até hoje.",np:1},
{v:27,t:"Depois todos os homens de Judá e de Jerusalém, com Josafá à frente, voltaram para Jerusalém com alegria, porque o Senhor os tinha alegrado com a derrota dos seus inimigos."},
{v:28,t:"Entraram em Jerusalém, na casa do Senhor, ao som das harpas, das cítaras e das trombetas."},
{v:29,t:"O terror de Deus caiu sobre todos os reinos das terras, quando souberam que o Senhor tinha combatido contra os inimigos de Israel."},
{v:30,t:"E o reino de Josafá ficou tranquilo, e o seu Deus lhe deu descanso de todos os lados."},
{s:"O fim do reinado de Josafá"},
{v:31,t:"Josafá reinou sobre Judá. Tinha trinta e cinco anos quando começou a reinar, e reinou vinte e cinco anos em Jerusalém. Sua mãe chamava-se Azuba, filha de Selaqui.",np:1},
{v:32,t:"Andou no caminho de Asa, seu pai, sem se desviar dele, fazendo o que é reto aos olhos do Senhor."},
{v:33,t:"Mas os lugares altos não foram suprimidos, e o povo ainda não tinha firmado o seu coração no Deus de seus pais."},
{v:34,t:"O resto dos feitos de Josafá, os primeiros e os últimos, está escrito na história de Jeú, filho de Hanani, que foi inserida no livro dos Reis de Israel."},
{v:35,t:"Depois disso, Josafá, rei de Judá, aliou-se com Ocozias, rei de Israel, que agia com impiedade.",np:1},
{v:36,t:"Associou-se com ele para construir navios que fossem a Társis, e construíram os navios em Asion-Gaber.",n:"Segundo 1 Reis 22,49-50, Josafá recusou a colaboração de Ocozias."},
{v:37,t:"Então Eliezer, filho de Dodias, de Maresa, profetizou contra Josafá, dizendo: Porque te aliaste com Ocozias, o Senhor destruiu a tua obra. E os navios se despedaçaram e não puderam ir a Társis."}
];

window.TEXTOS_SEED["2cronicas"][21] = [
{s:"Jorão, rei de Judá"},
{v:1,t:"Josafá adormeceu com seus pais e foi sepultado com eles na Cidade de Davi; e seu filho Jorão reinou em seu lugar."},
{v:2,t:"Jorão tinha irmãos, filhos de Josafá: Azarias, Jaiel, Zacarias, Azarias, Micael e Safatias; todos estes eram filhos de Josafá, rei de Israel.",n:"Rei de Israel: o cronista dá o título ao rei de Judá, herdeiro do verdadeiro Israel."},
{v:3,t:"Seu pai lhes tinha dado muitos presentes de prata, de ouro e de objetos preciosos, com cidades fortificadas em Judá; mas deu o reino a Jorão, porque era o primogênito."},
{v:4,t:"Quando Jorão tomou posse do reino de seu pai e se consolidou, matou à espada todos os seus irmãos e também alguns chefes de Israel."},
{v:5,t:"Jorão tinha trinta e dois anos quando começou a reinar, e reinou oito anos em Jerusalém.",np:1},
{v:6,t:"Andou no caminho dos reis de Israel, como tinha feito a casa de Acab, porque a sua mulher era filha de Acab; e fez o que é mau aos olhos do Senhor."},
{v:7,t:"Mas o Senhor não quis destruir a casa de Davi, por causa da aliança que tinha feito com Davi, conforme lhe tinha prometido dar sempre uma lâmpada, a ele e aos seus filhos."},
{v:8,t:"No seu tempo, Edom revoltou-se contra o domínio de Judá e fez para si um rei.",np:1},
{v:9,t:"Jorão partiu com os seus chefes e com todos os seus carros; levantou-se de noite e bateu os edomitas, que o tinham cercado, e os comandantes dos carros."},
{v:10,t:"Assim Edom se separou do domínio de Judá, até hoje. Naquele tempo também Lebna se revoltou contra o seu domínio, porque ele tinha abandonado o Senhor, Deus de seus pais."},
{v:11,t:"Além disso, construiu lugares altos nas montanhas de Judá, fez os habitantes de Jerusalém prostituir-se aos ídolos e desencaminhou Judá."},
{s:"A carta de Elias"},
{v:12,t:"Chegou-lhe então uma carta do profeta Elias, que dizia: Assim diz o Senhor, Deus de Davi, teu pai: Porque não andaste nos caminhos de Josafá, teu pai, nem nos caminhos de Asa, rei de Judá,",np:1,n:"Segundo 2 Reis 2-3, Elias já tinha sido arrebatado no tempo de Josafá. A carta seria uma profecia escrita deixada por ele, ou obra de um dos seus discípulos. É a única menção de Elias nas Crônicas."},
{v:13,t:"mas andaste no caminho dos reis de Israel, e fizeste Judá e os habitantes de Jerusalém prostituir-se, como a casa de Acab se prostituiu, e além disso mataste os teus irmãos, a família de teu pai, que eram melhores do que tu,"},
{v:14,t:"eis que o Senhor ferirá com um grande flagelo o teu povo, os teus filhos, as tuas mulheres e todos os teus bens;"},
{v:15,t:"e tu sofrerás de uma grave doença nas entranhas, até que, com a doença, as tuas entranhas saiam, dia após dia."},
{v:16,t:"O Senhor despertou contra Jorão a hostilidade dos filisteus e dos árabes que vivem perto dos etíopes.",np:1},
{v:17,t:"Eles subiram contra Judá, invadiram-no e levaram todos os bens que se encontraram no palácio do rei, e também os seus filhos e as suas mulheres; não lhe ficou nenhum filho, senão Joacaz, o mais novo.",n:"Joacaz é o Ocozias de 22,1: os dois nomes significam o Senhor segura, com as duas partes invertidas."},
{v:18,t:"Depois de tudo isso, o Senhor o feriu nas entranhas com uma doença incurável."},
{v:19,t:"Passaram-se os dias, e, ao fim de dois anos, as suas entranhas saíram por causa da doença, e ele morreu em meio a dores atrozes. O seu povo não acendeu em sua honra o fogo, como tinha feito para os seus pais."},
{v:20,t:"Tinha trinta e dois anos quando começou a reinar, e reinou oito anos em Jerusalém. Partiu sem deixar saudade, e o sepultaram na Cidade de Davi, mas não nos túmulos dos reis."}
];

window.TEXTOS_SEED["2cronicas"][22] = [
{s:"Ocozias, rei de Judá"},
{v:1,t:"Os habitantes de Jerusalém fizeram rei, em lugar de Jorão, Ocozias, seu filho mais novo, porque o bando que viera com os árabes ao acampamento tinha matado todos os mais velhos. Assim reinou Ocozias, filho de Jorão, rei de Judá."},
{v:2,t:"Ocozias tinha vinte e dois anos quando começou a reinar, e reinou um ano em Jerusalém. Sua mãe chamava-se Atalia, neta de Amri.",n:"Vinte e dois: assim a Nova Vulgata, com 2 Reis 8,26; o hebraico diz aqui quarenta e dois, o que é impossível, pois seu pai morreu com quarenta anos (21,20)."},
{v:3,t:"Também ele andou nos caminhos da casa de Acab, porque sua mãe o aconselhava a agir impiamente."},
{v:4,t:"Fez o que é mau aos olhos do Senhor, como a casa de Acab, porque, depois da morte de seu pai, foram eles os seus conselheiros, para a sua ruína."},
{v:5,t:"Seguindo os seus conselhos, foi com Jorão, filho de Acab, rei de Israel, combater contra Hazael, rei da Síria, em Ramot de Galaad; e os arameus feriram Jorão."},
{v:6,t:"Jorão voltou a Jezrael para se tratar das feridas que tinha recebido naquele combate. E Ocozias, filho de Jorão, rei de Judá, desceu a Jezrael para visitar Jorão, filho de Acab, que estava doente."},
{s:"A morte de Ocozias"},
{v:7,t:"Foi por disposição de Deus que Ocozias, para a sua ruína, veio visitar Jorão; pois, quando chegou, saiu com Jorão ao encontro de Jeú, filho de Namsi, que o Senhor tinha ungido para exterminar a casa de Acab.",np:1},
{v:8,t:"Enquanto Jeú fazia justiça contra a casa de Acab, encontrou os chefes de Judá e os sobrinhos de Ocozias, que estavam a serviço de Ocozias, e matou-os."},
{v:9,t:"Depois procurou Ocozias, que foi apanhado escondido em Samaria; trouxeram-no a Jeú, que o matou. Deram-lhe sepultura, porque diziam: É filho de Josafá, que buscou o Senhor de todo o coração. E não ficou ninguém da casa de Ocozias capaz de reinar.",n:"O relato difere de 2 Reis 9,27-28, onde Ocozias, ferido, morre em Meguido e é sepultado em Jerusalém."},
{s:"Atalia usurpa o trono"},
{v:10,t:"Quando Atalia, mãe de Ocozias, viu que o seu filho tinha morrido, levantou-se e exterminou toda a descendência real da casa de Judá.",np:1},
{v:11,t:"Mas Josaba, filha do rei, tomou Joás, filho de Ocozias, e o tirou às escondidas do meio dos filhos do rei que estavam sendo mortos, e o pôs com a sua ama no quarto das camas. Assim Josaba, filha do rei Jorão, mulher do sacerdote Joiada e irmã de Ocozias, o escondeu de Atalia, e ela não o matou.",n:"Só as Crônicas dizem que Josaba era mulher do sacerdote Joiada: o sacerdócio salva a descendência de Davi."},
{v:12,t:"Ele ficou escondido com eles na casa de Deus durante seis anos, enquanto Atalia reinava sobre o país."}
];

window.TEXTOS_SEED["2cronicas"][23] = [
{s:"Joiada proclama Joás rei"},
{v:1,t:"No sétimo ano, Joiada tomou coragem e fez aliança com os chefes de cem: Azarias, filho de Jeroam; Ismael, filho de Joanã; Azarias, filho de Obed; Maasias, filho de Adaías; e Elisafat, filho de Zecri.",n:"O cronista reconta 2 Reis 11: em lugar dos mercenários estrangeiros, são os levitas que guardam o rei no templo, porque ninguém mais podia entrar nele."},
{v:2,t:"Eles percorreram Judá, reuniram os levitas de todas as cidades de Judá e os chefes das famílias de Israel, e vieram a Jerusalém."},
{v:3,t:"Toda a assembleia fez aliança com o rei na casa de Deus. Joiada disse-lhes: Eis o filho do rei! Ele reinará, como o Senhor disse a respeito dos filhos de Davi."},
{v:4,t:"Eis, pois, o que haveis de fazer:"},
{v:5,t:"um terço de vós, sacerdotes e levitas, que entrais de serviço no sábado, guardará as portas; outro terço estará no palácio do rei, e outro terço na porta do Fundamento; e todo o povo estará nos átrios da casa do Senhor."},
{v:6,t:"Ninguém entre na casa do Senhor, a não ser os sacerdotes e os levitas que estão de serviço: estes poderão entrar, porque estão consagrados; e todo o povo observará as prescrições do Senhor."},
{v:7,t:"Os levitas cercarão o rei, cada um com as armas na mão; e quem entrar no templo será morto. Acompanhareis o rei quando ele entrar e quando sair."},
{v:8,t:"Os levitas e todo o Judá fizeram tudo o que o sacerdote Joiada tinha ordenado. Cada um tomou os seus homens, os que entravam de serviço no sábado e os que saíam de serviço no sábado; porque o sacerdote Joiada não tinha dispensado as turmas.",np:1},
{v:9,t:"O sacerdote Joiada deu aos chefes de cem as lanças, os escudos grandes e os escudos pequenos do rei Davi, que estavam na casa de Deus."},
{v:10,t:"E postou todo o povo, cada um com a arma na mão, desde o lado direito do templo até o lado esquerdo, entre o altar e o templo, em volta do rei."},
{v:11,t:"Então fizeram sair o filho do rei, puseram-lhe o diadema e as insígnias e o proclamaram rei. Joiada e os seus filhos o ungiram e gritaram: Viva o rei!"},
{s:"A morte de Atalia"},
{v:12,t:"Atalia ouviu o clamor do povo que corria e aclamava o rei, e foi ter com o povo, na casa do Senhor.",np:1},
{v:13,t:"Viu o rei de pé no seu estrado, à entrada, e os chefes e as trombetas junto do rei, e todo o povo da terra em festa, tocando as trombetas, e os cantores com os instrumentos de música, dirigindo o louvor. Então Atalia rasgou as vestes e gritou: Traição! Traição!"},
{v:14,t:"Mas o sacerdote Joiada fez sair os chefes de cem que comandavam o exército e lhes disse: Levai-a para fora do recinto; e quem a seguir, seja morto à espada. Porque o sacerdote tinha dito: Não a mateis na casa do Senhor."},
{v:15,t:"Agarraram-na, e, quando ela chegou à entrada da porta dos Cavalos do palácio real, ali a mataram."},
{s:"A aliança e a reforma de Joiada"},
{v:16,t:"Joiada fez uma aliança entre si, todo o povo e o rei, para que fossem o povo do Senhor.",np:1},
{v:17,t:"Todo o povo foi ao templo de Baal e o demoliu; despedaçaram os seus altares e as suas imagens, e mataram Matã, sacerdote de Baal, diante dos altares."},
{v:18,t:"Joiada confiou a guarda da casa do Senhor aos sacerdotes levitas, que Davi tinha distribuído em classes na casa do Senhor, para oferecerem os holocaustos ao Senhor, como está escrito na lei de Moisés, com alegria e cânticos, segundo as disposições de Davi."},
{v:19,t:"Pôs também porteiros às portas da casa do Senhor, para que não entrasse ninguém impuro por qualquer motivo."},
{v:20,t:"Depois tomou os chefes de cem, os nobres, os governantes do povo e todo o povo da terra, e fizeram descer o rei da casa do Senhor; entraram no palácio pela porta Superior e fizeram o rei sentar-se no trono real."},
{v:21,t:"Todo o povo da terra se alegrou, e a cidade ficou tranquila. Atalia tinha sido morta à espada."}
];

window.TEXTOS_SEED["2cronicas"][24] = [
{s:"Joás restaura o templo"},
{v:1,t:"Joás tinha sete anos quando começou a reinar, e reinou quarenta anos em Jerusalém. Sua mãe chamava-se Sébia, de Bersabeia."},
{v:2,t:"Joás fez o que é reto aos olhos do Senhor durante toda a vida do sacerdote Joiada.",n:"Durante a vida de Joiada, e não depois: o cronista contará a queda de Joás depois da morte do sacerdote (versículos 17-22)."},
{v:3,t:"Joiada deu-lhe duas mulheres, e ele gerou filhos e filhas."},
{v:4,t:"Depois disso, Joás resolveu restaurar a casa do Senhor.",np:1},
{v:5,t:"Reuniu os sacerdotes e os levitas e lhes disse: Ide pelas cidades de Judá e recolhei de todo o Israel dinheiro para reparar cada ano a casa do vosso Deus; e fazei isso depressa. Mas os levitas não se apressaram."},
{v:6,t:"Então o rei chamou Joiada, o chefe, e lhe disse: Por que não cuidaste de que os levitas trouxessem de Judá e de Jerusalém o imposto fixado por Moisés, servo do Senhor, e pela assembleia de Israel, para a tenda do testemunho?",n:"O imposto do santuário, de meio siclo por pessoa (Êxodo 30,11-16), que no tempo de Jesus ainda se pagava ao templo (Mateus 17,24)."},
{v:7,t:"Porque a ímpia Atalia e os seus filhos tinham arruinado a casa de Deus e tinham empregado para os baals todas as coisas consagradas da casa do Senhor."},
{v:8,t:"Por ordem do rei, fizeram um cofre e o puseram do lado de fora, junto à porta da casa do Senhor.",np:1},
{v:9,t:"E proclamaram em Judá e em Jerusalém que se trouxesse ao Senhor o imposto que Moisés, servo de Deus, tinha fixado para Israel no deserto."},
{v:10,t:"Todos os chefes e todo o povo alegraram-se, e traziam e lançavam no cofre, até enchê-lo."},
{v:11,t:"Quando chegava o tempo de levar o cofre aos oficiais do rei, por meio dos levitas, e viam que havia muito dinheiro, vinham o secretário do rei e o delegado do sumo sacerdote, esvaziavam o cofre e o levavam de volta ao seu lugar. Assim faziam dia após dia, e juntaram uma grande quantidade de dinheiro."},
{v:12,t:"O rei e Joiada o entregavam aos encarregados das obras da casa do Senhor, que contratavam cortadores de pedra e carpinteiros para restaurar a casa do Senhor, e também trabalhadores do ferro e do bronze para consertar a casa do Senhor."},
{v:13,t:"Os operários trabalharam, e as obras de reparação progrediram nas suas mãos; restauraram a casa de Deus no seu estado primitivo e a consolidaram."},
{v:14,t:"Quando terminaram, levaram ao rei e a Joiada o resto do dinheiro, e com ele fizeram objetos para a casa do Senhor: objetos para o serviço e para os holocaustos, taças e outros objetos de ouro e de prata. E ofereceram continuamente holocaustos na casa do Senhor durante toda a vida de Joiada.",n:"Segundo 2 Reis 12,14, com o dinheiro não se faziam objetos; o cronista fala talvez do dinheiro que sobrou, depois das obras."},
{s:"A morte de Joiada e a infidelidade de Joás"},
{v:15,t:"Joiada envelheceu, cheio de dias, e morreu; tinha cento e trinta anos quando morreu.",np:1},
{v:16,t:"Sepultaram-no na Cidade de Davi, com os reis, porque tinha feito o bem em Israel, para com Deus e para com a sua casa.",n:"O sacerdote é sepultado com os reis, honra que será negada a Joás (versículo 25)."},
{v:17,t:"Depois da morte de Joiada, os chefes de Judá vieram prostrar-se diante do rei; e o rei, lisonjeado, lhes deu ouvidos."},
{v:18,t:"Abandonaram a casa do Senhor, Deus de seus pais, e serviram aos postes sagrados e aos ídolos. Por causa desse pecado, a ira de Deus caiu sobre Judá e sobre Jerusalém."},
{v:19,t:"O Senhor enviou-lhes profetas para reconduzi-los a ele; eles os advertiram, mas não os quiseram ouvir."},
{v:20,t:"Então o Espírito de Deus revestiu Zacarias, filho do sacerdote Joiada, que se pôs de pé diante do povo e disse: Assim diz Deus: Por que transgredis os mandamentos do Senhor? Não prosperareis. Porque abandonastes o Senhor, ele vos abandonou.",np:1},
{v:21,t:"Mas conspiraram contra ele e, por ordem do rei, o apedrejaram no átrio da casa do Senhor.",n:"Jesus lembrará este mártir: desde o sangue de Abel até o sangue de Zacarias, que foi morto entre o santuário e o altar (Mateus 23,35; Lucas 11,51). Na Bíblia hebraica, as Crônicas são o último livro: Abel e Zacarias são o primeiro e o último justo assassinado."},
{v:22,t:"O rei Joás não se lembrou da bondade que Joiada, pai de Zacarias, tinha tido para com ele, e matou-lhe o filho. Este disse ao morrer: Que o Senhor veja e peça contas!",n:"O pedido de justiça do mártir contrasta com a oração de Estêvão e de Jesus, que perdoam aos seus assassinos (Lucas 23,34; Atos 7,60)."},
{s:"O castigo e a morte de Joás"},
{v:23,t:"Passado um ano, o exército da Síria subiu contra Joás, veio a Judá e a Jerusalém, exterminou todos os chefes do povo e enviou todo o despojo ao rei de Damasco.",np:1},
{v:24,t:"Embora o exército da Síria tivesse vindo com poucos homens, o Senhor entregou nas suas mãos um exército muito grande, porque tinham abandonado o Senhor, Deus de seus pais. Assim fizeram justiça contra Joás."},
{v:25,t:"Quando se retiraram, deixando-o gravemente ferido, os seus servos conspiraram contra ele, por causa do sangue do filho do sacerdote Joiada, e o mataram no seu leito, e ele morreu. Sepultaram-no na Cidade de Davi, mas não nos túmulos dos reis."},
{v:26,t:"Os que conspiraram contra ele foram Zabad, filho de Semaat, a amonita, e Jozabad, filho de Semarit, a moabita."},
{v:27,t:"Quanto aos seus filhos, ao pesado tributo que lhe foi imposto e à restauração da casa de Deus, está escrito no comentário do livro dos Reis. E seu filho Amasias reinou em seu lugar."}
];

window.TEXTOS_SEED["2cronicas"][25] = [
{s:"Amasias, rei de Judá"},
{v:1,t:"Amasias tinha vinte e cinco anos quando começou a reinar, e reinou vinte e nove anos em Jerusalém. Sua mãe chamava-se Joadan, de Jerusalém."},
{v:2,t:"Fez o que é reto aos olhos do Senhor, mas não de coração íntegro."},
{v:3,t:"Quando o reino se consolidou nas suas mãos, matou os servos que tinham assassinado o rei, seu pai;"},
{v:4,t:"mas não matou os filhos deles, segundo o que está escrito na Lei, no livro de Moisés, onde o Senhor ordenou: Os pais não serão mortos pelos filhos, nem os filhos pelos pais; cada um morrerá pelo seu próprio pecado."},
{s:"A guerra contra Edom"},
{v:5,t:"Amasias reuniu os homens de Judá e os organizou por famílias, sob chefes de mil e chefes de cem, para todo o Judá e Benjamim. Fez o recenseamento dos que tinham vinte anos para cima, e encontrou trezentos mil homens escolhidos, aptos para a guerra, que manejavam a lança e o escudo.",np:1},
{v:6,t:"Contratou também de Israel cem mil guerreiros valentes, por cem talentos de prata."},
{v:7,t:"Mas um homem de Deus foi ter com ele e disse: Ó rei, não vá contigo o exército de Israel, porque o Senhor não está com Israel, com nenhum dos filhos de Efraim."},
{v:8,t:"Se pensas que a força do exército decide a guerra, Deus te fará cair diante do inimigo; porque Deus tem o poder de ajudar e de fazer cair."},
{v:9,t:"Amasias disse ao homem de Deus: E que será dos cem talentos que dei à tropa de Israel? O homem de Deus respondeu: O Senhor pode dar-te muito mais do que isso."},
{v:10,t:"Então Amasias separou a tropa que lhe tinha vindo de Efraim, para que voltasse para a sua terra; e eles, muito irritados contra Judá, voltaram para a sua terra, cheios de cólera."},
{v:11,t:"Amasias, cheio de coragem, conduziu o seu povo ao vale do Sal e matou dez mil homens de Seir.",np:1},
{v:12,t:"Os filhos de Judá capturaram vivos outros dez mil, levaram-nos ao alto de um rochedo e os precipitaram do alto, e todos se despedaçaram."},
{v:13,t:"Entretanto, a tropa que Amasias tinha despedido, para que não fosse com ele à guerra, lançou-se sobre as cidades de Judá, desde Samaria até Bet-Horon; mataram três mil pessoas e levaram um grande despojo."},
{v:14,t:"Depois de derrotar os edomitas, Amasias trouxe os deuses dos filhos de Seir, fez deles os seus deuses, prostrou-se diante deles e queimou-lhes incenso.",np:1,n:"Adorar os deuses de um povo vencido era um absurdo, como o profeta lhe fará notar."},
{v:15,t:"Por isso a ira do Senhor inflamou-se contra Amasias, e ele lhe enviou um profeta, que lhe disse: Por que buscaste os deuses deste povo, que não puderam livrar o seu povo das tuas mãos?"},
{v:16,t:"Enquanto ele ainda falava, o rei lhe disse: Acaso te nomeamos conselheiro do rei? Cala-te! Por que queres ser morto? O profeta calou-se, mas disse: Sei que Deus decidiu destruir-te, porque fizeste isto e não ouviste o meu conselho."},
{s:"A guerra contra Israel"},
{v:17,t:"Amasias, rei de Judá, depois de se aconselhar, mandou dizer a Joás, filho de Joacaz, filho de Jeú, rei de Israel: Vem, enfrentemo-nos!",np:1},
{v:18,t:"Joás, rei de Israel, mandou responder a Amasias, rei de Judá: O cardo do Líbano mandou dizer ao cedro do Líbano: Dá a tua filha por mulher ao meu filho. Mas os animais selvagens do Líbano passaram e pisaram o cardo."},
{v:19,t:"Tu disseste: Derrotei Edom!, e o teu coração se ensoberbeceu. Fica em casa. Por que provocar uma desgraça, para caíres, tu e Judá contigo?"},
{v:20,t:"Mas Amasias não o ouviu, porque Deus assim tinha disposto, para entregá-los nas mãos do inimigo, por terem buscado os deuses de Edom."},
{v:21,t:"Joás, rei de Israel, subiu, e ele e Amasias, rei de Judá, enfrentaram-se em Bet-Sames, que pertence a Judá."},
{v:22,t:"Judá foi derrotado por Israel, e cada um fugiu para a sua tenda."},
{v:23,t:"Joás, rei de Israel, prendeu em Bet-Sames Amasias, rei de Judá, filho de Joás, filho de Joacaz, e o levou a Jerusalém. Abriu na muralha de Jerusalém uma brecha de quatrocentos côvados, desde a porta de Efraim até a porta do Ângulo.",n:"Joacaz é o rei Ocozias (21,17)."},
{v:24,t:"Tomou todo o ouro e toda a prata, e todos os objetos que se encontravam na casa de Deus, confiados a Obed-Edom, e os tesouros do palácio real, e também reféns; e voltou para Samaria.",n:"Obed-Edom: um descendente do guarda da arca, cuja família estava encarregada do armazém do templo (1 Crônicas 26,15)."},
{v:25,t:"Amasias, filho de Joás, rei de Judá, viveu ainda quinze anos depois da morte de Joás, filho de Joacaz, rei de Israel.",np:1},
{v:26,t:"O resto dos feitos de Amasias, os primeiros e os últimos, está escrito no livro dos Reis de Judá e de Israel."},
{v:27,t:"Desde que Amasias se afastou do Senhor, tramaram contra ele uma conspiração em Jerusalém, e ele fugiu para Laquis; mas mandaram atrás dele até Laquis, e ali o mataram."},
{v:28,t:"Trouxeram-no sobre cavalos e o sepultaram com seus pais na Cidade de Davi."}
];

window.TEXTOS_SEED["2cronicas"][26] = [
{s:"Ozias, rei de Judá"},
{v:1,t:"Todo o povo de Judá tomou Ozias, que tinha dezesseis anos, e o proclamou rei em lugar de Amasias, seu pai.",n:"Ozias é chamado Azarias em 2 Reis 14,21 e 15,1-7."},
{v:2,t:"Foi ele que reconstruiu Elat e a devolveu a Judá, depois que o rei adormeceu com seus pais."},
{v:3,t:"Ozias tinha dezesseis anos quando começou a reinar, e reinou cinquenta e dois anos em Jerusalém. Sua mãe chamava-se Jequelia, de Jerusalém."},
{v:4,t:"Fez o que é reto aos olhos do Senhor, em tudo como tinha feito Amasias, seu pai."},
{v:5,t:"Buscou a Deus durante a vida de Zacarias, que o instruía no temor de Deus; e, enquanto buscou o Senhor, Deus o fez prosperar.",n:"Zacarias: um conselheiro do rei, de resto desconhecido. No temor de Deus: assim a Nova Vulgata, com as versões antigas; o hebraico diz nas visões de Deus."},
{v:6,t:"Saiu a combater os filisteus, derrubou as muralhas de Gat, de Jabne e de Azoto, e construiu cidades no território de Azoto e entre os filisteus.",np:1},
{v:7,t:"Deus o ajudou contra os filisteus, contra os árabes que habitavam em Gur-Baal e contra os meunitas."},
{v:8,t:"Os amonitas pagavam tributo a Ozias, e a sua fama chegou até a entrada do Egito, porque se tornou muito poderoso."},
{v:9,t:"Ozias construiu torres em Jerusalém, sobre a porta do Ângulo, sobre a porta do Vale e sobre o Ângulo, e as fortificou."},
{v:10,t:"Construiu também torres no deserto e cavou muitas cisternas, porque tinha muito gado na Sefelá e na planície; tinha também agricultores e vinhateiros nas montanhas e nos campos férteis, porque amava a terra.",n:"Amava a terra: o rei agricultor. A arqueologia encontrou no deserto de Judá fortalezas e cisternas desta época."},
{v:11,t:"Ozias tinha um exército de guerreiros que saíam em campanha por divisões, segundo o recenseamento feito pelo escriba Jeiel e pelo oficial Maasias, sob as ordens de Hananias, um dos chefes do rei.",np:1},
{v:12,t:"O número total dos chefes de famílias, guerreiros valentes, era de dois mil e seiscentos."},
{v:13,t:"Sob as suas ordens havia um exército de trezentos e sete mil e quinhentos homens aptos para a guerra, fortes e valentes para ajudar o rei contra o inimigo."},
{v:14,t:"Ozias forneceu a todo o exército escudos, lanças, capacetes, couraças, arcos e fundas para atirar pedras."},
{v:15,t:"Em Jerusalém mandou fazer máquinas, inventadas por engenheiros, para ficarem nas torres e nos ângulos das muralhas, para atirar flechas e grandes pedras. A sua fama espalhou-se ao longe, porque foi ajudado de modo maravilhoso, até se tornar poderoso."},
{s:"O orgulho de Ozias"},
{v:16,t:"Mas, quando se tornou poderoso, o seu coração se ensoberbeceu, para a sua ruína: foi infiel ao Senhor seu Deus e entrou no templo do Senhor para queimar incenso no altar do incenso.",np:1,n:"O pecado de Ozias é o orgulho: querer ser também sacerdote, apoderando-se de uma função reservada aos filhos de Aarão (Números 18,1-7)."},
{v:17,t:"O sacerdote Azarias entrou atrás dele, com oitenta sacerdotes do Senhor, homens corajosos."},
{v:18,t:"Opuseram-se ao rei Ozias e lhe disseram: Não te cabe, Ozias, queimar incenso ao Senhor, mas aos sacerdotes, filhos de Aarão, que foram consagrados para isso. Sai do santuário, porque cometeste uma infidelidade, e isso não te dará glória diante do Senhor Deus."},
{v:19,t:"Ozias, que tinha na mão o incensório para queimar o incenso, irritou-se; e, enquanto se irritava contra os sacerdotes, apareceu-lhe a lepra na fronte, diante dos sacerdotes, na casa do Senhor, junto ao altar do incenso."},
{v:20,t:"O sumo sacerdote Azarias e todos os sacerdotes olharam para ele e viram que estava leproso na fronte; fizeram-no sair dali imediatamente, e ele mesmo se apressou em sair, porque o Senhor o tinha ferido."},
{v:21,t:"O rei Ozias ficou leproso até o dia da sua morte, e morou numa casa à parte, leproso, porque tinha sido excluído da casa do Senhor. Seu filho Joatão governava o palácio e julgava o povo da terra."},
{v:22,t:"O resto dos feitos de Ozias, os primeiros e os últimos, foi escrito pelo profeta Isaías, filho de Amós.",np:1,n:"Isaías recebeu a sua vocação no ano da morte do rei Ozias (Isaías 6,1)."},
{v:23,t:"Ozias adormeceu com seus pais, e o sepultaram com seus pais no campo dos túmulos reais, porque diziam: É leproso. E seu filho Joatão reinou em seu lugar."}
];

window.TEXTOS_SEED["2cronicas"][27] = [
{s:"Joatão, rei de Judá"},
{v:1,t:"Joatão tinha vinte e cinco anos quando começou a reinar, e reinou dezesseis anos em Jerusalém. Sua mãe chamava-se Jerusa, filha de Sadoc."},
{v:2,t:"Fez o que é reto aos olhos do Senhor, em tudo como tinha feito Ozias, seu pai; somente não entrou no templo do Senhor. Mas o povo continuava a proceder mal.",n:"Somente não entrou no templo: não repetiu o pecado do pai."},
{v:3,t:"Foi ele que construiu a porta Superior da casa do Senhor e fez muitas obras na muralha do Ofel."},
{v:4,t:"Construiu também cidades na montanha de Judá, e fortalezas e torres nos bosques."},
{v:5,t:"Combateu contra o rei dos amonitas e venceu-os; e os amonitas lhe deram naquele ano cem talentos de prata, dez mil coros de trigo e dez mil de cevada; e o mesmo lhe deram no segundo e no terceiro ano."},
{v:6,t:"Joatão tornou-se poderoso, porque dirigiu os seus caminhos diante do Senhor seu Deus."},
{v:7,t:"O resto dos feitos de Joatão, todas as suas guerras e os seus caminhos, estão escritos no livro dos Reis de Israel e de Judá.",np:1},
{v:8,t:"Tinha vinte e cinco anos quando começou a reinar, e reinou dezesseis anos em Jerusalém."},
{v:9,t:"Joatão adormeceu com seus pais, e o sepultaram na Cidade de Davi; e seu filho Acaz reinou em seu lugar."}
];

window.TEXTOS_SEED["2cronicas"][28] = [
{s:"Acaz, rei de Judá"},
{v:1,t:"Acaz tinha vinte anos quando começou a reinar, e reinou dezesseis anos em Jerusalém. Não fez o que é reto aos olhos do Senhor, como Davi, seu pai,"},
{v:2,t:"mas andou nos caminhos dos reis de Israel, e chegou a fazer imagens de metal fundido para os baals."},
{v:3,t:"Queimou incenso no vale de Ben-Enom e fez passar pelo fogo os seus filhos, segundo as abominações das nações que o Senhor tinha expulsado diante dos filhos de Israel.",n:"O vale de Ben-Enom, ao sul de Jerusalém, onde se sacrificavam crianças; o seu nome, Geena, tornou-se imagem do inferno (Mateus 5,22)."},
{v:4,t:"Oferecia sacrifícios e queimava incenso nos lugares altos, sobre as colinas e debaixo de toda árvore frondosa."},
{s:"A guerra com a Síria e com Israel"},
{v:5,t:"Por isso o Senhor seu Deus o entregou nas mãos do rei da Síria, que o derrotou e levou muitos cativos para Damasco. Foi entregue também nas mãos do rei de Israel, que lhe infligiu uma grande derrota.",np:1},
{v:6,t:"Faceia, filho de Romelias, matou num só dia cento e vinte mil homens de Judá, todos guerreiros valentes, porque tinham abandonado o Senhor, Deus de seus pais."},
{v:7,t:"Zecri, guerreiro de Efraim, matou Maasias, filho do rei, Ezricam, mordomo do palácio, e Elcana, o segundo depois do rei."},
{v:8,t:"Os filhos de Israel levaram cativos, dos seus irmãos, duzentos mil mulheres, meninos e meninas, e tomaram deles um grande despojo, que levaram para Samaria."},
{s:"O profeta Oded e a libertação dos cativos"},
{v:9,t:"Havia ali um profeta do Senhor chamado Oded. Ele saiu ao encontro do exército que voltava a Samaria e lhes disse: O Senhor, Deus de vossos pais, irritado contra Judá, entregou-os nas vossas mãos, mas vós os matastes com uma fúria que chegou até o céu.",np:1},
{v:10,t:"E agora quereis fazer dos filhos de Judá e de Jerusalém vossos escravos e vossas escravas! Mas vós mesmos não sois culpados diante do Senhor vosso Deus?"},
{v:11,t:"Ouvi-me, pois: devolvei os cativos que tomastes dos vossos irmãos, porque a ira ardente do Senhor está sobre vós."},
{v:12,t:"Então alguns chefes dos filhos de Efraim — Azarias, filho de Joanã; Baraquias, filho de Mosolamot; Ezequias, filho de Selum; e Amasa, filho de Adali — levantaram-se contra os que voltavam da guerra"},
{v:13,t:"e lhes disseram: Não trareis aqui os cativos, porque quereis acrescentar aos nossos pecados e às nossas culpas uma culpa contra o Senhor. A nossa culpa já é grande, e a ira ardente do Senhor está sobre Israel."},
{v:14,t:"Os guerreiros deixaram os cativos e o despojo diante dos chefes e de toda a assembleia."},
{v:15,t:"E os homens designados nominalmente levantaram-se, tomaram os cativos e, com o despojo, vestiram todos os que estavam nus; deram-lhes roupas e sandálias, deram-lhes de comer e de beber e os ungiram; puseram sobre jumentos todos os que não podiam andar, e os levaram a Jericó, a cidade das Palmeiras, para junto dos seus irmãos. Depois voltaram para Samaria.",n:"Um dos episódios mais belos das Crônicas, e o único em que os israelitas do Norte são louvados. Jesus parece lembrá-lo na parábola do bom samaritano, que também cuida do ferido, o unge e o leva num animal, na estrada de Jericó (Lucas 10,30-35)."},
{s:"Acaz pede socorro à Assíria"},
{v:16,t:"Naquele tempo, o rei Acaz mandou pedir socorro ao rei da Assíria.",np:1},
{v:17,t:"Os edomitas tinham vindo de novo, tinham derrotado Judá e levado cativos."},
{v:18,t:"Os filisteus tinham invadido as cidades da Sefelá e do Negueb de Judá; tomaram Bet-Sames, Aialon, Gederot, Soco e as suas aldeias, Tamna e as suas aldeias, Ganzo e as suas aldeias, e estabeleceram-se nelas."},
{v:19,t:"Porque o Senhor tinha humilhado Judá por causa de Acaz, rei de Israel, que tinha deixado Judá sem freio e tinha sido infiel ao Senhor.",n:"Rei de Israel: o cronista dá o título aos reis de Judá; aqui talvez com ironia, porque Acaz andou nos caminhos dos reis de Israel."},
{v:20,t:"Teglat-Falasar, rei da Assíria, veio contra ele e o oprimiu, em vez de fortalecê-lo."},
{v:21,t:"Pois Acaz despojou a casa do Senhor, o palácio real e as casas dos chefes, e deu tudo ao rei da Assíria; mas de nada lhe serviu."},
{s:"A impiedade de Acaz"},
{v:22,t:"Mesmo no tempo da sua angústia, continuou a ser infiel ao Senhor, ele, o rei Acaz.",np:1},
{v:23,t:"Ofereceu sacrifícios aos deuses de Damasco, que o tinham derrotado, dizendo: Os deuses dos reis da Síria os ajudam; oferecerei sacrifícios a eles, e eles me ajudarão. Mas eles foram a causa da sua ruína e da de todo o Israel."},
{v:24,t:"Acaz juntou os objetos da casa de Deus e os despedaçou; fechou as portas da casa do Senhor e fez para si altares em todas as esquinas de Jerusalém.",n:"Fechar o templo: é o ponto mais baixo da história de Judá antes do exílio. Ezequias, seu filho, começará por reabri-lo (29,3)."},
{v:25,t:"Em todas as cidades de Judá construiu lugares altos para queimar incenso a outros deuses, e irritou o Senhor, Deus de seus pais."},
{v:26,t:"O resto dos seus feitos e todos os seus caminhos, os primeiros e os últimos, estão escritos no livro dos Reis de Judá e de Israel.",np:1},
{v:27,t:"Acaz adormeceu com seus pais, e o sepultaram na cidade, em Jerusalém; mas não o puseram nos túmulos dos reis de Israel. E seu filho Ezequias reinou em seu lugar."}
];

window.TEXTOS_SEED["2cronicas"][29] = [
{s:"Ezequias purifica o templo"},
{v:1,t:"Ezequias começou a reinar com vinte e cinco anos, e reinou vinte e nove anos em Jerusalém. Sua mãe chamava-se Abi, filha de Zacarias.",n:"O cronista dedica quatro capítulos a Ezequias (29-32), novo Davi e novo Salomão, e sobretudo à sua reforma do culto, que 2 Reis 18,4 apenas menciona."},
{v:2,t:"Fez o que é reto aos olhos do Senhor, em tudo como tinha feito Davi, seu pai."},
{v:3,t:"No primeiro mês do primeiro ano do seu reinado, abriu as portas da casa do Senhor e as restaurou.",np:1},
{v:4,t:"Mandou vir os sacerdotes e os levitas, reuniu-os na praça oriental"},
{v:5,t:"e lhes disse: Ouvi-me, levitas! Santificai-vos agora e santificai a casa do Senhor, Deus de vossos pais, e tirai do santuário toda impureza."},
{v:6,t:"Os nossos pais foram infiéis e fizeram o que é mau aos olhos do Senhor nosso Deus; abandonaram-no, desviaram o rosto da morada do Senhor e lhe voltaram as costas."},
{v:7,t:"Fecharam até as portas do vestíbulo, apagaram as lâmpadas, não queimaram incenso nem ofereceram holocaustos no santuário ao Deus de Israel."},
{v:8,t:"Por isso a ira do Senhor caiu sobre Judá e sobre Jerusalém, e ele os entregou ao terror, à desolação e à zombaria, como vedes com os vossos olhos."},
{v:9,t:"Eis que os nossos pais caíram à espada, e os nossos filhos, as nossas filhas e as nossas mulheres foram levados cativos por causa disso."},
{v:10,t:"Agora, pois, tenho no coração fazer uma aliança com o Senhor, Deus de Israel, para que afaste de nós o ardor da sua ira."},
{v:11,t:"Meus filhos, não sejais negligentes, porque o Senhor vos escolheu para estardes diante dele, para o servirdes, para serdes os seus ministros e lhe queimardes incenso."},
{v:12,t:"Então levantaram-se os levitas: Maat, filho de Amasai, e Joel, filho de Azarias, dos filhos de Caat; dos filhos de Merari, Cis, filho de Abdi, e Azarias, filho de Jalelel; dos filhos de Gérson, Joá, filho de Zima, e Éden, filho de Joá;",np:1},
{v:13,t:"dos filhos de Elisafã, Semri e Jeiel; dos filhos de Asaf, Zacarias e Matanias;"},
{v:14,t:"dos filhos de Hemã, Jaiel e Semei; dos filhos de Iditun, Semeías e Oziel."},
{v:15,t:"Reuniram os seus irmãos, santificaram-se e vieram, segundo a ordem do rei e as palavras do Senhor, para purificar a casa do Senhor."},
{v:16,t:"Os sacerdotes entraram no interior da casa do Senhor para purificá-la, e levaram para o átrio da casa do Senhor toda a impureza que encontraram no templo do Senhor; e os levitas a recolheram e a levaram para fora, para a torrente do Cedron."},
{v:17,t:"Começaram a purificação no primeiro dia do primeiro mês; no oitavo dia do mês chegaram ao vestíbulo do Senhor, e em oito dias purificaram a casa do Senhor; e no décimo sexto dia do primeiro mês terminaram."},
{v:18,t:"Depois foram ter com o rei Ezequias e disseram: Purificamos toda a casa do Senhor, o altar dos holocaustos com todos os seus utensílios, e a mesa dos pães da proposição com todos os seus utensílios.",np:1},
{v:19,t:"E todos os objetos que o rei Acaz tinha profanado durante o seu reinado, na sua infidelidade, nós os restauramos e santificamos: eis que estão diante do altar do Senhor."},
{s:"O sacrifício de expiação"},
{v:20,t:"O rei Ezequias levantou-se de madrugada, reuniu os chefes da cidade e subiu à casa do Senhor.",np:1},
{v:21,t:"Trouxeram sete touros, sete carneiros, sete cordeiros e sete bodes, em sacrifício pelo pecado, pelo reino, pelo santuário e por Judá; e o rei ordenou aos sacerdotes, filhos de Aarão, que os oferecessem sobre o altar do Senhor."},
{v:22,t:"Imolaram os touros, e os sacerdotes recolheram o sangue e o derramaram sobre o altar; imolaram os carneiros e derramaram o sangue sobre o altar; imolaram os cordeiros e derramaram o sangue sobre o altar."},
{v:23,t:"Depois trouxeram os bodes do sacrifício pelo pecado diante do rei e da assembleia, que impuseram as mãos sobre eles;"},
{v:24,t:"e os sacerdotes os imolaram e fizeram com o seu sangue, sobre o altar, a expiação por todo o Israel; porque o rei tinha ordenado o holocausto e o sacrifício pelo pecado por todo o Israel.",n:"Por todo o Israel: Ezequias pensa também nas tribos do Norte, que a Assíria acabava de deportar (30,1-9)."},
{v:25,t:"Estabeleceu os levitas na casa do Senhor, com címbalos, harpas e cítaras, segundo as disposições de Davi, de Gad, vidente do rei, e do profeta Natã; porque a ordem vinha do Senhor, por meio dos seus profetas.",np:1},
{v:26,t:"Os levitas estavam de pé com os instrumentos de Davi, e os sacerdotes com as trombetas."},
{v:27,t:"Ezequias ordenou que se oferecesse o holocausto sobre o altar; e, no momento em que começou o holocausto, começou também o cântico do Senhor, ao som das trombetas e dos instrumentos de Davi, rei de Israel."},
{v:28,t:"Toda a assembleia se prostrava, os cantores cantavam e as trombetas soavam, até que se terminou o holocausto."},
{v:29,t:"Terminado o holocausto, o rei e todos os que estavam com ele inclinaram-se e se prostraram."},
{v:30,t:"O rei Ezequias e os chefes mandaram os levitas louvar o Senhor com as palavras de Davi e do vidente Asaf; e eles o louvaram com alegria, inclinaram-se e se prostraram.",n:"As palavras de Davi e de Asaf: os salmos, que já formavam o livro de cânticos do templo."},
{s:"Os sacrifícios do povo"},
{v:31,t:"Então Ezequias disse: Agora que vos consagrastes ao Senhor, aproximai-vos e trazei sacrifícios e ofertas de ação de graças à casa do Senhor. E a assembleia trouxe sacrifícios e ofertas de ação de graças, e todos os de coração generoso trouxeram holocaustos.",np:1},
{v:32,t:"O número dos holocaustos que a assembleia trouxe foi de setenta touros, cem carneiros e duzentos cordeiros, tudo em holocausto ao Senhor."},
{v:33,t:"As ofertas consagradas foram seiscentos bois e três mil ovelhas."},
{v:34,t:"Mas os sacerdotes eram poucos e não bastavam para esfolar todos os holocaustos; por isso os levitas, seus irmãos, os ajudaram até terminar o trabalho e até que os sacerdotes se santificassem, porque os levitas tinham sido mais retos de coração do que os sacerdotes para se santificarem.",n:"O cronista, amigo dos levitas, nota com certa ironia a lentidão dos sacerdotes."},
{v:35,t:"Houve também holocaustos em abundância, com a gordura dos sacrifícios de comunhão e as libações dos holocaustos. Assim foi restabelecido o culto da casa do Senhor."},
{v:36,t:"Ezequias e todo o povo alegraram-se pelo que Deus tinha preparado para o povo, porque a coisa se fez de repente."}
];
